1	//! The release executor.
2	//!
3	//! Every run starts from a fresh in-memory state and observes each provider
4	//! before acting, so a rerun adopts whatever an earlier run already landed.
5	
6	use std::collections::BTreeSet;
7	use std::time::Duration;
8	
9	use michi_graph::{Dag, Order};
10	
11	use callisto_model::{
12	    ApplyPermit, OperationEvent, OperationState, ReleaseExecutionStateV1, ReleaseIntentV1, ReleaseOperationId,
13	    ReleaseOperationRole, ReleaseRunEnvelopeV1, ReleaseStateError,
14	};
15	
16	use crate::GraphError;
17	
18	use super::release::{ReleasePreflight, ReleaseProviderSet};
19	use super::release_artifacts::VerifiedArtifactManifest;
20	use crate::error::ReleasePreconditionRequirement;
