86	fn warn_if_registry_version_adopted(operation: &ReleaseOperationId) {
87	    let package = match &operation.role {
88	        ReleaseOperationRole::RegistryPublish { .. } => &operation.package,
89	        ReleaseOperationRole::PlatformPublish { platform, .. } => platform.name(),
90	        _ => return,
91	    };
92	    eprintln!(
93	        "warning: {package} {} is already published; skipping",
94	        operation.version
95	    );
96	}
