98	/// The single seam through which this executor changes state.
99	fn apply(
100	    state: &mut ReleaseExecutionStateV1,
101	    operation: &ReleaseOperationId,
102	    event: &OperationEvent,
103	) -> Result<(), GraphError> {
104	    state
105	        .apply(operation, event)
106	        .map(|_| ())
107	        .map_err(|source| match source {
108	            ReleaseStateError::EvidenceRejected(source) => GraphError::ReleaseProviderObservation { source },
109	            source => GraphError::ReleaseExecutionState { source },
110	        })
111	}
112	
113	/// Refuses to report success until every operation has an observed terminal
114	/// success state.
115	fn require_terminal_success(intent: &ReleaseIntentV1, state: &ReleaseExecutionStateV1) -> Result<(), GraphError> {
116	    let count = intent
117	        .operations
118	        .iter()
119	        .filter(|operation| {
120	            !state
121	                .operation_state(operation.id())
122	                .is_some_and(OperationState::is_success)
123	        })
124	        .count();
125	    if count == 0 {
126	        Ok(())
127	    } else {
128	        Err(GraphError::ReleaseIncomplete { count })
129	    }
130	}
