132	/// Requires the verification capability whenever `intent` declares compiled
133	/// binary slots. Its private constructor already proved both manifest binding
134	/// and local byte/attestation identity.
135	fn require_verified_artifact_manifest(
136	    intent: &ReleaseIntentV1,
137	    artifacts: Option<&VerifiedArtifactManifest<'_>>,
138	) -> Result<(), GraphError> {
139	    match (intent.artifact_slots.is_empty(), artifacts) {
140	        (true, None) => Ok(()),
141	        (true, Some(artifacts)) if !callisto_model::python_publishes(intent).is_empty() => {
142	            require_artifact_manifest_matches_intent(intent, Some(artifacts.manifest()))
143	        }
144	        (true, Some(_)) => Err(GraphError::ReleaseInvariant {
145	            detail: "verified artifact manifest supplied for a release intent with nothing to seal".to_owned(),
146	        }),
147	        (false, Some(artifacts)) => require_artifact_manifest_matches_intent(intent, Some(artifacts.manifest())),
148	        (false, None) => Err(GraphError::ReleasePreconditionUnmet {
149	            requirement: ReleasePreconditionRequirement::VerifiedArtifactManifest,
150	        }),
151	    }
152	}
153	
154	/// Validates the serializable manifest independently of local byte and
155	/// attestation verification. Kept as a focused invariant helper for tests;
156	/// production execution requires `VerifiedArtifactManifest` above.
157	fn require_artifact_manifest_matches_intent(
158	    intent: &ReleaseIntentV1,
159	    artifacts: Option<&callisto_model::ArtifactManifestV1>,
160	) -> Result<(), GraphError> {
161	    match (intent.artifact_slots.is_empty(), artifacts) {
162	        (true, None) => Ok(()),
163	        (true, Some(manifest)) | (false, Some(manifest)) => manifest
164	            .validate_for_intent(intent)
165	            .map_err(|source| GraphError::ArtifactManifest { source }),
166	        (false, None) => Err(GraphError::ReleasePreconditionUnmet {
167	            requirement: ReleasePreconditionRequirement::ArtifactManifestProvided,
168	        }),
169	    }
170	}
