187	/// Looks at every issued operation until one is shown, so the run goes on with whatever that unlocks, or gives up
188	/// once the registries have had their whole window.
189	///
190	/// Each look is one observation per issued operation, and the issued operations are looked at together: the wait is
191	/// the slowest registry's, not the sum of them.
192	fn settle_issued<P: ReleaseProviderSet + ?Sized>(
193	    capability: &P,
194	    artifacts: Option<&VerifiedArtifactManifest<'_>>,
195	    state: &mut ReleaseExecutionStateV1,
196	    issued: &mut BTreeSet<ReleaseOperationId>,
197	) -> Result<(), GraphError> {
198	    let window = issued
199	        .iter()
200	        .map(|id| capability.confirmation_window(id))
201	        .max()
202	        .unwrap_or_default();
203	    let mut waited = Duration::ZERO;
204	    let mut step = 0;
205	    loop {
206	        let mut progressed = false;
207	        for id in issued.clone() {
208	            if let Some(evidence) = capability.settle(&id, artifacts)? {
209	                apply(state, &id, &OperationEvent::Confirmed { evidence })?;
210	                issued.remove(&id);
211	                progressed = true;
212	            }
213	        }
214	        if issued.is_empty() || progressed {
215	            return Ok(());
216	        }
217	        let remaining = window.saturating_sub(waited);
218	        if remaining.is_zero() {
219	            let mut unconfirmed = issued.iter();
220	            let Some(first) = unconfirmed.next() else {
221	                return Ok(());
222	            };
223	            for other in unconfirmed {
224	                eprintln!("warning: {other} is also still not shown by its registry");
225	            }
226	            return Err(GraphError::RegistryPublishUnconfirmed {
227	                package: first.package.name().to_owned(),
228	                version: first.version.clone(),
229	                waited: window,
230	            });
231	        }
232	        let wait = crate::commands::release::provider::policy::visibility_backoff(step).min(remaining);
233	        capability.pause(wait);
234	        waited += wait;
235	        step += 1;
236	    }
237	}
