239	/// A registry publish, which is issued now and shown later.
240	fn is_registry_effect(id: &ReleaseOperationId) -> bool {
241	    matches!(
242	        id.role,
243	        ReleaseOperationRole::RegistryPublish { .. } | ReleaseOperationRole::PlatformPublish { .. }
244	    )
245	}
