277	/// [`eligible_in`] for a caller that has only the intent and issued nothing.
278	#[cfg(test)]
279	pub(crate) fn eligible_operations(
280	    intent: &ReleaseIntentV1,
281	    state: &ReleaseExecutionStateV1,
282	) -> Vec<ReleaseOperationId> {
283	    let dag = operation_dag(intent).expect("a test intent is a valid DAG");
284	    eligible_in(&dag, state, &BTreeSet::new())
285	}
