442	    /// The production tag provider behind the real executor, with an effect counter in place of the real publish.
443	    struct TagOnlyProviders<'a> {
444	        intent: ReleaseIntentV1,
445	        operation: crate::commands::release::provider::PreparedOperation,
446	        root: &'a std::path::Path,
447	        runner: &'a dyn callisto_model::CommandRunner,
448	        effects: std::cell::Cell<usize>,
449	    }
450	
451	    impl TagOnlyProviders<'_> {
452	        fn request<'r>(
453	            &'r self,
454	            id: &'r ReleaseOperationId,
455	        ) -> crate::commands::release::provider::ProviderRequest<'r> {
456	            crate::commands::release::provider::ProviderRequest {
457	                id,
458	                operation: &self.operation,
459	                artifacts: None,
460	            }
461	        }
462	    }
