508	    /// A git whose `rev-parse` fails fatally and whose remote reads as empty; it remembers each subcommand it ran.
509	    struct BrokenLocalGit(std::sync::Mutex<Vec<String>>);
510	
511	    impl callisto_model::CommandRunner for BrokenLocalGit {
512	        fn run(
513	            &self,
514	            _program: &str,
515	            args: &[&str],
516	            _cwd: &std::path::Path,
517	        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
518	            let subcommand = args.first().copied().unwrap_or_default();
519	            self.0.lock().unwrap().push(subcommand.to_owned());
520	            let (exit_code, stdout, stderr) = match subcommand {
521	                "remote" => (0, "https://github.com/orin-dx/callisto", ""),
522	                "rev-parse" => (128, "", "fatal: not a git repository\n"),
523	                _ => (0, "", ""),
524	            };
525	            Ok(callisto_model::CommandOutput {
526	                exit_code: Some(exit_code),
527	                stdout: stdout.to_owned(),
528	                stderr: stderr.to_owned(),
529	            })
530	        }
531	    }
