555	        let dir = tempfile::tempdir().unwrap();
556	        let runner = BrokenLocalGit(std::sync::Mutex::new(Vec::new()));
557	        let providers = TagOnlyProviders {
558	            operation: crate::commands::release::provider::PreparedOperation::Tag(
559	                crate::commands::release::provider::TagOperation {
560	                    name: callisto_model::TagName::new_unchecked("demo@1.0.0".to_owned()),
