101	/// The production provider set: every operation is routed to the adapter
102	/// prepared for it during fresh validation, so no caller-supplied path,
103	/// endpoint, tag, package name, or version can reach a provider.
104	impl ReleaseProviderSet for ValidatedReleaseIntent<'_> {
