109	    fn recheck_trust(&self) -> Result<(), GraphError> {
110	        let evidence =
111	            callisto_model::vcs::GitAccess::new(&self.prepared.root, self.runner).observe_git_commit_trust()?;
112	        if evidence.identity() != self.prepared.trust.identity() || source_from_trust(&evidence) != self.prepared.source
113	        {
114	            return Err(GraphError::ReleaseIntentStale {
115	                reason: StaleReason::trust_evidence_changed(),
116	            });
117	        }
118	        // An unreadable remote propagates as itself; only a readable, different remote is "stale".
119	        if let Some(expected) = self.prepared.git_remote.as_ref() {
120	            recheck_git_remote(&self.prepared.root, self.runner, expected)?;
121	        }
