289	/// the exact operation DAG before creating an opaque authorization capability.
290	pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
291	    root: &Path,
292	    locator: &L,
293	    runner: &'a R,
294	    received: ReleaseIntentV1,
