299	/// [`validate_release_intent`] for a local `callisto release`, which may run on any branch.
300	pub fn validate_local_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
301	    root: &Path,
302	    locator: &L,
303	    runner: &'a R,
304	    received: ReleaseIntentV1,
305	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
306	    validate_intent(root, locator, runner, received, ReleaseCheckout::AnyHead)
