309	fn validate_intent<'a, L: ProjectLocator, R: CommandRunner>(
310	    root: &Path,
311	    locator: &L,
312	    runner: &'a R,
313	    received: ReleaseIntentV1,
314	    checkout: ReleaseCheckout,
315	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
316	    let root = canonical_root(root)?;
317	    let workspace = Workspace::load(root.clone(), locator, runner)?;
318	    let trust = observe_git_trust(&workspace, received.trust_profile, checkout)?;
319	    let source = source_from_trust(&trust);
320	    let artifact_policy = artifact_policy_from_intent(&received)?;
321	    // This is an integrity re-derivation, not a fresh plan: any diagnostic it would
322	    // raise was already surfaced when `received` was first derived.
323	    let (expected, prepared) = derive_release_intent_with_prepared(
324	        &workspace,
325	        &received.decision,
326	        source.clone(),
327	        received.trust_profile,
328	        artifact_policy.as_ref(),
329	        &mut Vec::new(),
330	    )?;
331	    let final_trust = observe_git_trust(&workspace, received.trust_profile, checkout)?;
332	    if expected != received || final_trust.identity() != trust.identity() {
333	        return Err(GraphError::ReleaseIntentStale {
334	            reason: StaleReason::intent_differs_from_fresh_derivation(),
335	        });
336	    }
337	
338	    // Plan time is the last point before any effect at which an unusable
339	    // provider is still cheap to reject.
340	    for operation in prepared.operations.values() {
341	        checked_provider_for(operation)?;
342	    }
343	
344	    Ok(ValidatedReleaseIntent {
345	        prepared: PreparedReleaseInputs {
346	            root,
347	            source,
348	            trust: final_trust,
349	            git_remote: prepared.git_remote,
350	            operations: prepared.operations,
351	        },
352	        intent: received,
353	        runner,
354	        file_sets: PypiFileSets::default(),
355	    })
356	}
