358	/// The packages in `among` with any operation of `prepared` that is not observed exactly satisfied.
359	///
360	/// Other packages' operations are not observed. An observation that fails counts as unsatisfied, so the run
361	/// itself reports it.
362	pub(crate) fn unsatisfied_packages(
363	    root: &Path,
364	    runner: &dyn CommandRunner,
365	    prepared: &super::derive::PreparedDerivation,
366	    among: &std::collections::BTreeSet<callisto_model::ReleasePackageId>,
367	) -> std::collections::BTreeSet<callisto_model::ReleasePackageId> {
368	    let context = ProviderContext::new(root, runner, prepared.git_remote.as_ref());
369	    prepared
370	        .operations
371	        .iter()
372	        .filter(|(id, _)| among.contains(&id.package))
373	        .filter(|(id, operation)| {
374	            let observed = checked_provider_for(operation).and_then(|provider| {
375	                provider.observe(
376	                    &context,
377	                    &ProviderRequest {
378	                        id,
379	                        operation,
380	                        artifacts: None,
381	                    },
382	                )
383	            });
384	            !matches!(observed, Ok(ProviderObservationV1::Exact { .. }))
385	        })
386	        .map(|(id, _)| id.package.clone())
387	        .collect()
388	}
