390	/// The packages in `among` with a registry publish already observed exactly satisfied.
391	///
392	/// A failed observation counts as not published; the run reports it itself.
393	pub(crate) fn published_packages(
394	    root: &Path,
395	    runner: &dyn CommandRunner,
396	    prepared: &super::derive::PreparedDerivation,
397	    among: &std::collections::BTreeSet<callisto_model::ReleasePackageId>,
398	) -> std::collections::BTreeSet<callisto_model::ReleasePackageId> {
399	    let context = ProviderContext::new(root, runner, prepared.git_remote.as_ref());
400	    prepared
401	        .operations
402	        .iter()
403	        .filter(|(id, operation)| {
404	            among.contains(&id.package) && matches!(operation, PreparedOperation::RegistryPublish(_))
405	        })
406	        .filter(|(id, operation)| {
407	            let observed = checked_provider_for(operation).and_then(|provider| {
408	                provider.observe(
409	                    &context,
410	                    &ProviderRequest {
411	                        id,
412	                        operation,
413	                        artifacts: None,
414	                    },
415	                )
416	            });
417	            matches!(observed, Ok(ProviderObservationV1::Exact { .. }))
418	        })
419	        .map(|(id, _)| id.package.clone())
420	        .collect()
421	}
422	
423	pub(crate) fn canonical_root(root: &Path) -> Result<std::path::PathBuf, GraphError> {
424	    dunce::canonicalize(root).map_err(|error| GraphError::ReleaseInputRead {
425	        path: root.to_path_buf(),
426	        message: error.to_string(),
427	    })
428	}
429	
430	/// Which checkout a release may run from.
431	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
432	pub(crate) enum ReleaseCheckout {
433	    /// The exact detached commit a CI intent is planned and executed from.
434	    Detached,
435	    /// A local checkout on any branch; the source is HEAD's commit.
436	    AnyHead,
437	}
438	
439	pub(crate) fn observe_source<R: CommandRunner, D: DependencyResolver>(
440	    workspace: &Workspace<'_, R, D>,
441	    trust_profile: ExecutionTrustProfileV1,
442	    checkout: ReleaseCheckout,
443	) -> Result<SourceIdentity, GraphError> {
444	    Ok(source_from_trust(&observe_git_trust(
445	        workspace,
446	        trust_profile,
447	        checkout,
448	    )?))
449	}
450	
451	fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
452	    workspace: &Workspace<'_, R, D>,
453	    trust_profile: ExecutionTrustProfileV1,
454	    checkout: ReleaseCheckout,
455	) -> Result<GitCommitTrustEvidence, GraphError> {
456	    if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit) {
457	        return Err(ReleaseIntentError::UnsupportedTrustProfile.into());
458	    }
459	    let evidence = workspace.git_access().observe_git_commit_trust()?;
460	    if evidence.canonical_root() != workspace.root {
461	        return Err(GraphError::ReleasePreconditionUnmet {
462	            requirement: ReleasePreconditionRequirement::CanonicalRootMatchesWorkspace,
463	        });
464	    }
465	    if checkout == ReleaseCheckout::Detached && evidence.head_disposition() != GitHeadDisposition::Detached {
466	        return Err(GraphError::ReleasePreconditionUnmet {
467	            requirement: ReleasePreconditionRequirement::DetachedHead,
468	        });
469	    }
470	    Ok(evidence)
471	}
