1	//! The commit that set a package's version, so a rerun after a half-finished release cannot tag later code.
2	
3	use std::collections::BTreeSet;
4	
5	use callisto_manifests::{read_identity, VersionSource};
6	use callisto_model::vcs::GitAccess;
7	use callisto_model::{ManifestDecl, ReleaseDecisionV1, ReleasePackageId};
8	
9	use crate::changed::package_paths;
10	use crate::{DependencyResolver, GraphError, Workspace};
11	
12	/// How many commits touching the manifest are read looking for the one that set the version.
13	const HISTORY_LIMIT: usize = 100;
14	
15	/// A package that changed after the commit that set the version it is about to release.
16	pub(super) struct MovedPast {
17	    pub package: ReleasePackageId,
18	    pub version: String,
19	    pub version_commit: String,
20	    pub newer_commits: usize,
21	}
22	
23	/// The selected packages with commits touching their files after the commit that set their release version.
24	///
25	/// A package whose version commit cannot be found (an inherited or unreadable version, or a long history) is not
26	/// reported: the check only ever refuses on evidence. `resumable` packages are tagged on HEAD already.
27	pub(super) fn packages_moved_past_their_version<R: callisto_model::CommandRunner, D: DependencyResolver>(
28	    workspace: &Workspace<'_, R, D>,
29	    decision: &ReleaseDecisionV1,
30	    resumable: &BTreeSet<ReleasePackageId>,
31	) -> Result<Vec<MovedPast>, GraphError> {
32	    let git = workspace.git_access();
33	    let mut moved = Vec::new();
34	    for package in workspace.graph.packages() {
35	        let ids = crate::commands::release_decision::release_package_ids(&workspace.identity, package)?;
36	        let Some(entry) = decision
37	            .entries
38	            .iter()
39	            .find(|entry| ids.contains(&entry.package) && !resumable.contains(&entry.package))
40	        else {
41	            continue;
42	        };
43	        let Some(manifest) = package.canonical_manifests().next() else {
44	            continue;
45	        };
46	        let version = entry.target_version.render().to_owned();
47	        let Some(version_commit) = commit_setting_version(git, manifest, &version)? else {
48	            continue;
49	        };
50	        let newer_commits = git.commits_since(Some(&version_commit), &package_paths(package))?.len();
51	        if newer_commits > 0 {
52	            moved.push(MovedPast {
53	                package: entry.package.clone(),
54	                version,
55	                version_commit,
56	                newer_commits,
57	            });
58	        }
59	    }
60	    Ok(moved)
61	}
62	
63	/// The newest commit whose manifest holds `version` while its parent's does not.
64	fn commit_setting_version(
65	    git: &GitAccess<'_>,
66	    manifest: &ManifestDecl,
67	    version: &str,
68	) -> Result<Option<String>, GraphError> {
69	    for commit in git
70	        .commits_since(None, std::slice::from_ref(&manifest.path))?
71	        .iter()
72	        .take(HISTORY_LIMIT)
73	    {
74	        let sha = commit.sha.as_str();
75	        if version_at(git, sha, manifest)?.as_deref() != Some(version) {
76	            continue;
77	        }
78	        // A root commit has no parent, so the version was set there.
79	        let parent = version_at(git, &format!("{sha}^"), manifest).unwrap_or(None);
80	        if parent.as_deref() != Some(version) {
81	            return Ok(Some(sha.to_owned()));
82	        }
83	    }
84	    Ok(None)
85	}
86	
87	/// The literal version `manifest` declared at `rev`, if it held one.
88	fn version_at(git: &GitAccess<'_>, rev: &str, manifest: &ManifestDecl) -> Result<Option<String>, GraphError> {
89	    let Some(text) = git.read_at(rev, &manifest.path)? else {
90	        return Ok(None);
91	    };
92	    Ok(
93	        match read_identity(manifest.format, &text, &manifest.path)
94	            .ok()
95	            .and_then(|identity| identity.version)
96	        {
97	            Some(VersionSource::Literal(version)) => Some(version),
98	            _ => None,
99	        },
100	    )
101	}
102	
103	#[cfg(test)]
104	mod tests {
105	    use std::path::Path;
106	
107	    use super::*;
108	    use crate::commands::release::tests::{fixture, RealGitRunner};
109	    use crate::IgnoreWalkLocator;
110	
111	    fn git(root: &Path, args: &[&str]) -> String {
112	        let output = std::process::Command::new("git")
113	            .args(args)
114	            .current_dir(root)
115	            .output()
116	            .unwrap();
117	        assert!(output.status.success(), "git {args:?}");
118	        String::from_utf8_lossy(&output.stdout).trim().to_owned()
119	    }
120	
121	    fn moved(root: &Path) -> Vec<(String, String)> {
122	        let workspace = Workspace::load(root.to_path_buf(), &IgnoreWalkLocator::new(root), &RealGitRunner).unwrap();
123	        let decision = crate::commands::release_decision::derive_release_roster(&workspace, &[], &BTreeSet::new())
124	            .unwrap()
125	            .expect("unreleased packages");
126	        packages_moved_past_their_version(&workspace, &decision, &BTreeSet::new())
127	            .unwrap()
128	            .into_iter()
129	            .map(|moved| (moved.package.to_string(), moved.version_commit))
130	            .collect()
131	    }
132	
133	    #[test]
134	    fn a_package_untouched_since_its_version_commit_is_not_reported() {
135	        let (dir, _) = fixture();
136	        assert!(moved(dir.path()).is_empty());
137	    }
138	
139	    #[test]
140	    fn a_later_commit_in_the_package_is_reported_with_the_version_commit() {
141	        let (dir, _) = fixture();
142	        let version_commit = git(dir.path(), &["rev-parse", "HEAD"]);
143	        std::fs::write(dir.path().join("NOTES.md"), "later\n").unwrap();
144	        git(dir.path(), &["add", "."]);
145	        git(dir.path(), &["commit", "-q", "-m", "later"]);
146	        assert_eq!(
147	            moved(dir.path()),
