48	impl std::fmt::Debug for ValidatedReleaseIntent<'_> {
49	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
50	        formatter
51	            .debug_struct("ValidatedReleaseIntent")
52	            .field("intent", &self.intent)
53	            .finish_non_exhaustive()
54	    }
55	}
