72	    /// Builds every Python publish of the intent into `outdir` and returns the packages built.
73	    ///
74	    /// This is the credential-free build job's work: the executing job later uploads these exact files.
75	    pub fn build_python_distributions(&self, outdir: &Path) -> Result<Vec<String>, GraphError> {
76	        let context = self.context();
77	        let mut built = Vec::new();
78	        for (id, prepared) in &self.prepared.operations {
79	            let PreparedOperation::RegistryPublish(operation) = prepared else {
80	                continue;
81	            };
82	            if id.package.ecosystem() != callisto_model::Ecosystem::Pypi {
83	                continue;
84	            }
85	            super::provider::build_python_into(&context, operation, outdir)?;
