91	    fn prepared_operation(&self, id: &ReleaseOperationId) -> Result<&PreparedOperation, GraphError> {
92	        self.prepared
93	            .operations
94	            .get(id)
95	            .ok_or_else(|| GraphError::ReleaseInvariant {
96	                detail: format!("no prepared operation for `{id:?}`"),
97	            })
