176	    fn defers_confirmation(&self, id: &ReleaseOperationId) -> bool {
177	        let Ok(operation) = self.prepared_operation(id) else {
178	            return false;
179	        };
180	        checked_provider_for(operation).is_ok_and(|provider| {
181	            provider.defers_confirmation(&ProviderRequest {
182	                id,
183	                operation,
184	                artifacts: None,
185	            })
186	        })
187	    }
