189	    fn issue(
190	        &self,
191	        permit: &ApplyPermit,
192	        proof: &AbsentProof,
193	        id: &ReleaseOperationId,
194	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
195	    ) -> Result<(), GraphError> {
196	        let operation = self.prepared_operation(id)?;
197	        checked_provider_for(operation)?.issue(
198	            &self.context(),
199	            &ProviderRequest {
200	                id,
201	                operation,
202	                artifacts,
203	            },
204	            &EffectAuthorization { permit, proof },
205	        )
206	    }
