209	        let Ok(operation) = self.prepared_operation(id) else {
210	            return std::time::Duration::ZERO;
211	        };
212	        checked_provider_for(operation).map_or(std::time::Duration::ZERO, |provider| {
213	            provider.confirmation_window(&ProviderRequest {
