222	/// Builds a release intent from a fresh root-bound observation.
223	pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
224	    root: &Path,
225	    locator: &L,
226	    runner: &R,
227	    decision: &ReleaseDecisionV1,
228	    trust_profile: ExecutionTrustProfileV1,
229	) -> Result<ReleaseIntentV1, GraphError> {
230	    let root = canonical_root(root)?;
231	    let workspace = Workspace::load(root.clone(), locator, runner)?;
232	    let source = observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)?;
233	    let intent = derive_release_intent(
234	        &workspace,
235	        decision,
236	        source.clone(),
237	        trust_profile,
238	        None,
239	        GitRemoteRequirement::Required,
240	        &mut Vec::new(),
241	    )?;
242	
243	    // Recheck after all input reads. A concurrent edit or checkout cannot be
244	    // authorized merely because it happened after the first check.
245	    if observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)? != source {
246	        return Err(GraphError::ReleaseIntentStale {
247	            reason: StaleReason::source_identity_changed(),
248	        });
249	    }
250	    Ok(intent)
251	}
252	
253	/// Builds an intent whose declared binary slots are bound to the current
254	/// coordinator workflow. Callers recovering an old release source must pass
255	/// the current coordinator revision here, never substitute the source SHA.
256	///
257	/// Returns advisory diagnostics from derivation (e.g. an artifact owner selected
258	/// without its product) alongside the intent, for a caller to surface.
259	pub fn build_release_intent_with_artifacts<L: ProjectLocator, R: CommandRunner>(
260	    root: &Path,
261	    locator: &L,
262	    runner: &R,
263	    decision: &ReleaseDecisionV1,
264	    trust_profile: ExecutionTrustProfileV1,
265	    artifact_policy: ArtifactBuildPolicy,
266	) -> Result<(ReleaseIntentV1, Vec<callisto_model::Diagnostic>), GraphError> {
267	    let root = canonical_root(root)?;
268	    let workspace = Workspace::load(root.clone(), locator, runner)?;
269	    let source = observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)?;
270	    let mut diagnostics = Vec::new();
271	    let intent = derive_release_intent(
272	        &workspace,
273	        decision,
274	        source.clone(),
275	        trust_profile,
276	        Some(&artifact_policy),
277	        GitRemoteRequirement::Required,
278	        &mut diagnostics,
279	    )?;
280	    if observe_source(&workspace, trust_profile, ReleaseCheckout::Detached)? != source {
281	        return Err(GraphError::ReleaseIntentStale {
282	            reason: StaleReason::source_identity_changed(),
283	        });
284	    }
285	    Ok((intent, diagnostics))
286	}
287	
288	/// Re-observes root, config, package discovery, manifests, Git evidence, and
289	/// the exact operation DAG before creating an opaque authorization capability.
290	pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
291	    root: &Path,
292	    locator: &L,
293	    runner: &'a R,
294	    received: ReleaseIntentV1,
295	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
296	    validate_intent(root, locator, runner, received, ReleaseCheckout::Detached)
297	}
298	
299	/// [`validate_release_intent`] for a local `callisto release`, which may run on any branch.
300	pub fn validate_local_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
301	    root: &Path,
302	    locator: &L,
303	    runner: &'a R,
304	    received: ReleaseIntentV1,
305	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
306	    validate_intent(root, locator, runner, received, ReleaseCheckout::AnyHead)
307	}
308	
309	fn validate_intent<'a, L: ProjectLocator, R: CommandRunner>(
310	    root: &Path,
311	    locator: &L,
312	    runner: &'a R,
313	    received: ReleaseIntentV1,
314	    checkout: ReleaseCheckout,
315	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
316	    let root = canonical_root(root)?;
317	    let workspace = Workspace::load(root.clone(), locator, runner)?;
318	    let trust = observe_git_trust(&workspace, received.trust_profile, checkout)?;
319	    let source = source_from_trust(&trust);
320	    let artifact_policy = artifact_policy_from_intent(&received)?;
321	    // This is an integrity re-derivation, not a fresh plan: any diagnostic it would
322	    // raise was already surfaced when `received` was first derived.
323	    let (expected, prepared) = derive_release_intent_with_prepared(
324	        &workspace,
325	        &received.decision,
326	        source.clone(),
327	        received.trust_profile,
328	        artifact_policy.as_ref(),
329	        &mut Vec::new(),
330	    )?;
331	    let final_trust = observe_git_trust(&workspace, received.trust_profile, checkout)?;
332	    if expected != received || final_trust.identity() != trust.identity() {
333	        return Err(GraphError::ReleaseIntentStale {
334	            reason: StaleReason::intent_differs_from_fresh_derivation(),
335	        });
336	    }
337	
338	    // Plan time is the last point before any effect at which an unusable
339	    // provider is still cheap to reject.
340	    for operation in prepared.operations.values() {
341	        checked_provider_for(operation)?;
342	    }
343	
344	    Ok(ValidatedReleaseIntent {
345	        prepared: PreparedReleaseInputs {
346	            root,
347	            source,
348	            trust: final_trust,
349	            git_remote: prepared.git_remote,
350	            operations: prepared.operations,
351	        },
352	        intent: received,
353	        runner,
354	        file_sets: PypiFileSets::default(),
355	    })
356	}
357	
358	/// The packages in `among` with any operation of `prepared` that is not observed exactly satisfied.
359	///
360	/// Other packages' operations are not observed. An observation that fails counts as unsatisfied, so the run
361	/// itself reports it.
362	pub(crate) fn unsatisfied_packages(
363	    root: &Path,
364	    runner: &dyn CommandRunner,
365	    prepared: &super::derive::PreparedDerivation,
366	    among: &std::collections::BTreeSet<callisto_model::ReleasePackageId>,
367	) -> std::collections::BTreeSet<callisto_model::ReleasePackageId> {
368	    let context = ProviderContext::new(root, runner, prepared.git_remote.as_ref());
369	    prepared
370	        .operations
371	        .iter()
372	        .filter(|(id, _)| among.contains(&id.package))
373	        .filter(|(id, operation)| {
374	            let observed = checked_provider_for(operation).and_then(|provider| {
375	                provider.observe(
376	                    &context,
377	                    &ProviderRequest {
378	                        id,
379	                        operation,
380	                        artifacts: None,
381	                    },
382	                )
383	            });
384	            !matches!(observed, Ok(ProviderObservationV1::Exact { .. }))
385	        })
386	        .map(|(id, _)| id.package.clone())
387	        .collect()
388	}
389	
390	/// The packages in `among` with a registry publish already observed exactly satisfied.
391	///
392	/// A failed observation counts as not published; the run reports it itself.
393	pub(crate) fn published_packages(
394	    root: &Path,
395	    runner: &dyn CommandRunner,
396	    prepared: &super::derive::PreparedDerivation,
397	    among: &std::collections::BTreeSet<callisto_model::ReleasePackageId>,
398	) -> std::collections::BTreeSet<callisto_model::ReleasePackageId> {
399	    let context = ProviderContext::new(root, runner, prepared.git_remote.as_ref());
400	    prepared
401	        .operations
402	        .iter()
403	        .filter(|(id, operation)| {
404	            among.contains(&id.package) && matches!(operation, PreparedOperation::RegistryPublish(_))
405	        })
406	        .filter(|(id, operation)| {
407	            let observed = checked_provider_for(operation).and_then(|provider| {
408	                provider.observe(
409	                    &context,
410	                    &ProviderRequest {
411	                        id,
412	                        operation,
413	                        artifacts: None,
414	                    },
415	                )
416	            });
417	            matches!(observed, Ok(ProviderObservationV1::Exact { .. }))
418	        })
419	        .map(|(id, _)| id.package.clone())
420	        .collect()
