429	    /// The text of `path` (relative to this root) in `rev`'s tree, decoded lossily; `None` when it is absent.
430	    pub fn read_at(&self, rev: &str, path: &Path) -> Result<Option<String>, VcsError> {
431	        if !self.path_exists_at(rev, path)? {
432	            return Ok(None);
433	        }
434	        let spec = format!("{rev}:./{}", path.display());
435	        let args = ["show", &spec];
436	        let output = self.runner.run("git", &args, &self.root)?;
437	        if !output.success() {
438	            return Err(probe_failed(&args, &self.root, &output));
