443	    /// The most recent commit that added `path`, if it is committed.
444	    pub fn commit_adding(&self, path: &Path) -> Result<Option<String>, VcsError> {
445	        // A repository with no commits has no history to search; `git log` would fail there.
446	        if self.resolve_commit("HEAD")?.is_none() {
447	            return Ok(None);
448	        }
449	        let path = path.to_string_lossy();
450	        let args = ["log", "--diff-filter=A", "--format=%H", "-1", "--", &path];
