500	    /// it points at. An unresolvable ref resolves to `Ok(None)`, which
501	    /// callers treat as "no bound" / "infer over full history".
502	    pub fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
503	        let rev = format!("{refname}^{{commit}}");
504	        let args = ["rev-parse", "--verify", "--quiet", &rev];
