528	    /// A `since_ref` that is given but does not resolve is
529	    /// [`VcsError::RefNotFound`], never a silent unbounded walk.
530	    pub fn commits_since(&self, since_ref: Option<&str>, pathspecs: &[PathBuf]) -> Result<Vec<GitCommit>, VcsError> {
531	        let mut args: Vec<String> = vec![
532	            "log".to_string(),
533	            "--no-merges".to_string(),
534	            "--full-history".to_string(),
535	            format!("--format={RECORD_SEP}%H{FIELD_SEP}%B"),
536	        ];
537	
538	        match since_ref {
539	            Some(r) => args.push(format!("{r}..HEAD")),
540	            None => args.push("HEAD".to_string()),
541	        }
542	
543	        if !pathspecs.is_empty() {
544	            args.push("--".to_string());
545	            args.extend(pathspecs.iter().map(|p| p.display().to_string()));
546	        }
547	
548	        let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
549	        let output = self.runner.run("git", &arg_refs, &self.root)?;
550	
551	        if !output.success() {
552	            if let Some(r) = since_ref
553	                && self.resolve_commit(r)?.is_none()
554	            {
555	                return Err(VcsError::RefNotFound {
556	                    ref_name: r.to_string(),
557	                });
558	            }
559	            return Err(VcsError::Git(format!(
560	                "`git log` failed in `{}`: {}",
561	                self.root.display(),
562	                output.redacted_stderr()
563	            )));
564	        }
565	
566	        parse_git_log_output(&output.stdout, &self.root)
567	    }
