1	//! The local `callisto release` route: select every unreleased package and
2	//! derive its intent, for both the preview and the run.
3	
4	use std::path::Path;
5	
6	use callisto_model::{CommandRunner, ExecutionTrustProfileV1, ReleaseIntentV1, ReleasePackageId, SourceIdentity};
7	
8	use crate::{DependencyResolver, GraphError, ProjectLocator, Workspace};
9	
10	use super::binding::optional_git_remote;
11	use super::capability::{canonical_root, observe_source, published_packages, unsatisfied_packages, ReleaseCheckout};
12	use super::derive::{
13	    derive_release_intent, derive_release_intent_with_prepared, ArtifactBuildPolicy, GitRemoteRequirement,
14	};
15	use super::StaleReason;
16	
17	/// How a local release observes its source commit.
18	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
19	pub enum LocalReleaseSource {
20	    /// `--dry-run`: HEAD's commit, whatever the worktree state.
21	    Preview,
22	    /// A real run: HEAD's commit from a clean worktree, on any branch.
23	    Trusted,
24	}
25	
26	/// Why a workspace must release through the CI plan/build/execute route.
27	#[derive(Clone, Debug, PartialEq, Eq)]
28	pub enum CiReleaseRoute {
29	    /// The workspace declares `[[release.artifact]]` slots.
30	    ArtifactSlots,
31	    /// A package ships napi or maturin platform builds.
32	    PlatformPackage { package: String },
33	}
34	
35	impl std::fmt::Display for CiReleaseRoute {
36	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
37	        match self {
38	            CiReleaseRoute::ArtifactSlots => formatter.write_str("the workspace declares [[release.artifact]] slots"),
39	            CiReleaseRoute::PlatformPackage { package } => {
40	                write!(formatter, "package `{package}` ships napi/maturin platform builds")
41	            }
42	        }
43	    }
44	}
45	
46	/// The reason this workspace cannot release locally, if any.
47	pub fn ci_release_route<R: CommandRunner, D: DependencyResolver>(
48	    workspace: &Workspace<'_, R, D>,
49	) -> Result<Option<CiReleaseRoute>, GraphError> {
50	    if workspace
51	        .config
52	        .product_release
53	        .as_ref()
54	        .is_some_and(|release| !release.artifacts.is_empty())
55	    {
56	        return Ok(Some(CiReleaseRoute::ArtifactSlots));
57	    }
58	    if let Some(package) = workspace.graph.packages().find(|package| {
59	        super::derive::is_platform_package(package) || workspace.identity.platforms_of(&package.id).next().is_some()
60	    }) {
61	        return Ok(Some(CiReleaseRoute::PlatformPackage {
62	            package: package.id.display_name(),
63	        }));
64	    }
65	    let matrix = crate::commands::matrix(workspace, &crate::commands::MatrixOptions::default())?;
66	    Ok(matrix
67	        .platform_targets
68	        .keys()
69	        .next()
70	        .map(|package| CiReleaseRoute::PlatformPackage {
71	            package: package.clone(),
72	        }))
73	}
74	
75	/// A derived local release.
76	#[derive(Clone, Debug, PartialEq, Eq)]
77	pub struct LocalReleasePlan {
78	    pub intent: ReleaseIntentV1,
79	    /// A preview only: `origin` has no push URL, so tags carry no remote and a run would refuse.
80	    pub tags_unbound: bool,
81	    /// Advisory findings from derivation (e.g. an artifact owner selected without its product).
82	    pub diagnostics: Vec<callisto_model::Diagnostic>,
83	}
84	
85	/// Derives the intent for every unreleased package (or exactly `selections`).
86	///
87	/// This is the one plan derivation behind both `callisto release --dry-run`
88	/// and `callisto release`; `None` means nothing is unreleased.
89	pub fn plan_local_release<L: ProjectLocator, R: CommandRunner>(
90	    root: &Path,
91	    locator: &L,
92	    runner: &R,
93	    selections: &[ReleasePackageId],
94	    mode: LocalReleaseSource,
95	) -> Result<Option<LocalReleasePlan>, GraphError> {
96	    let root = canonical_root(root)?;
97	    let workspace = Workspace::load(root, locator, runner)?;
98	    plan_workspace_release(&workspace, selections, mode)
99	}
100	
101	/// The tagged releases on HEAD whose operations are not all observed satisfied: a rerun finishes them.
102	///
103	/// A tag proves only that the tag was created. Releases tagged on an older commit are settled and
104	/// never observed, so only a rerun at the release commit reaches the providers.
105	fn incomplete_tagged_releases<R: CommandRunner, D: DependencyResolver>(
106	    workspace: &Workspace<'_, R, D>,
107	    mode: LocalReleaseSource,
108	) -> Result<std::collections::BTreeSet<ReleasePackageId>, GraphError> {
109	    let head = workspace.git_access().head_sha()?;
110	    let tagged: std::collections::BTreeSet<ReleasePackageId> =
111	        crate::commands::release_decision::releases_tagged_at(workspace, &head)?
112	            .into_iter()
113	            .map(|entry| entry.package)
114	            .collect();
115	    if tagged.is_empty() {
116	        return Ok(tagged);
117	    }
118	    // Without an `origin` push URL a preview cannot observe anything, so it cannot call a tagged release finished.
119	    if mode == LocalReleaseSource::Preview && optional_git_remote(&workspace.root, workspace.runner)?.is_none() {
120	        return Ok(tagged);
121	    }
122	    let profile = ExecutionTrustProfileV1::GitCommit;
123	    let source = match mode {
124	        LocalReleaseSource::Preview => SourceIdentity::GitCommit { sha: head },
125	        LocalReleaseSource::Trusted => observe_source(workspace, profile, ReleaseCheckout::AnyHead)?,
126	    };
127	    // The roster a run would plan with every tagged release still open, so a dependency left untagged by the
128	    // failed run is part of it and the dependency checks see the same packages as the real derivation.
129	    let Some(decision) = crate::commands::release_decision::derive_release_roster(workspace, &[], &tagged)? else {
130	        return Ok(Default::default());
131	    };
132	    let (_, prepared) =
133	        derive_release_intent_with_prepared(workspace, &decision, source, profile, None, &mut Vec::new())?;
134	    Ok(unsatisfied_packages(
135	        &workspace.root,
136	        workspace.runner,
137	        &prepared,
138	        &tagged,
139	    ))
140	}
141	
142	/// Refuses to tag a version the registry already holds while its package has moved on since the commit that set it.
143	///
144	/// A release that stopped after publishing leaves exactly this state. A rerun on a later commit would tag code that
145	/// was never published, so it finishes from the version commit instead. Nothing is observed unless a package moved.
146	fn refuse_a_published_version_left_behind<R: CommandRunner, D: DependencyResolver>(
147	    workspace: &Workspace<'_, R, D>,
148	    decision: &callisto_model::ReleaseDecisionV1,
149	    resumable: &std::collections::BTreeSet<ReleasePackageId>,
150	    source: &SourceIdentity,
151	    profile: ExecutionTrustProfileV1,
152	    mode: LocalReleaseSource,
153	) -> Result<(), GraphError> {
154	    let moved = super::version_commit::packages_moved_past_their_version(workspace, decision, resumable)?;
155	    // Without an `origin` push URL a preview cannot observe the registry either.
156	    if moved.is_empty()
157	        || (mode == LocalReleaseSource::Preview && optional_git_remote(&workspace.root, workspace.runner)?.is_none())
158	    {
159	        return Ok(());
160	    }
161	    let (_, prepared) =
162	        derive_release_intent_with_prepared(workspace, decision, source.clone(), profile, None, &mut Vec::new())?;
163	    let among = moved.iter().map(|moved| moved.package.clone()).collect();
164	    let published = published_packages(&workspace.root, workspace.runner, &prepared, &among);
165	    match moved.into_iter().find(|moved| published.contains(&moved.package)) {
166	        Some(moved) => Err(GraphError::ReleasePublishedVersionMoved {
167	            package: moved.package.to_string(),
168	            version: moved.version,
169	            version_commit: moved.version_commit.chars().take(12).collect(),
170	            newer_commits: moved.newer_commits,
171	        }),
172	        None => Ok(()),
173	    }
174	}
175	
176	/// [`plan_local_release`] over an already-loaded workspace, e.g. one built from an in-memory config.
177	pub fn plan_workspace_release<R: CommandRunner, D: DependencyResolver>(
178	    workspace: &Workspace<'_, R, D>,
179	    selections: &[ReleasePackageId],
180	    mode: LocalReleaseSource,
181	) -> Result<Option<LocalReleasePlan>, GraphError> {
182	    let resumable = incomplete_tagged_releases(workspace, mode)?;
183	    let Some(decision) = crate::commands::release_decision::derive_release_roster(workspace, selections, &resumable)?
184	    else {
185	        return Ok(None);
186	    };
187	    let profile = ExecutionTrustProfileV1::GitCommit;
188	    let source = match mode {
189	        LocalReleaseSource::Preview => SourceIdentity::GitCommit {
190	            sha: workspace.git_access().head_sha()?,
191	        },
192	        LocalReleaseSource::Trusted => observe_source(workspace, profile, ReleaseCheckout::AnyHead)?,
193	    };
194	    refuse_a_published_version_left_behind(workspace, &decision, &resumable, &source, profile, mode)?;
195	    // A local run is its own orchestration: slots bind to the source commit.
196	    let artifact_policy = match (&workspace.config.product_release, &source) {
197	        (Some(release), SourceIdentity::GitCommit { sha }) if !release.artifacts.is_empty() => {
198	            release.forge_repository.clone().map(|repository| ArtifactBuildPolicy {
199	                repository,
200	                workflow_path: callisto_model::RELEASE_COORDINATOR_WORKFLOW_PATH.to_owned(),
201	                workflow_commit: sha.clone(),
202	            })
203	        }
204	        _ => None,
205	    };
206	    let remote = match mode {
207	        LocalReleaseSource::Preview => GitRemoteRequirement::OptionalForPreview,
208	        LocalReleaseSource::Trusted => GitRemoteRequirement::Required,
209	    };
210	    let mut diagnostics = Vec::new();
211	    let intent = derive_release_intent(
212	        workspace,
213	        &decision,
214	        source.clone(),
215	        profile,
216	        artifact_policy.as_ref(),
217	        remote,
218	        &mut diagnostics,
219	    )?;
220	    let tags_unbound = mode == LocalReleaseSource::Preview
221	        && intent
222	            .operations
223	            .iter()
224	            .any(|operation| operation.id().role == callisto_model::ReleaseOperationRole::Tag)
225	        && optional_git_remote(&workspace.root, workspace.runner)?.is_none();
226	    if mode == LocalReleaseSource::Trusted && observe_source(workspace, profile, ReleaseCheckout::AnyHead)? != source {
227	        return Err(GraphError::ReleaseIntentStale {
228	            reason: StaleReason::source_identity_changed(),
229	        });
230	    }
231	    Ok(Some(LocalReleasePlan {
232	        intent,
233	        tags_unbound,
234	        diagnostics,
235	    }))
236	}
