551	        if !output.success() {
552	            if let Some(r) = since_ref
553	                && self.resolve_commit(r)?.is_none()
554	            {
555	                return Err(VcsError::RefNotFound {
556	                    ref_name: r.to_string(),
557	                });
558	            }
559	            return Err(VcsError::Git(format!(
560	                "`git log` failed in `{}`: {}",
561	                self.root.display(),
562	                output.redacted_stderr()
563	            )));
564	        }
565	
566	        parse_git_log_output(&output.stdout, &self.root)
567	    }
568	
569	    /// Resolves every ref in `refs` to its commit with one `git rev-parse`.
570	    /// `None` when any of them does not resolve.
571	    pub fn resolve_commits(&self, refs: &[String]) -> Result<Option<Vec<CommitSha>>, VcsError> {
572	        let revs: Vec<String> = refs.iter().map(|r| format!("{r}^{{commit}}")).collect();
573	        let mut args = vec!["rev-parse"];
574	        args.extend(revs.iter().map(String::as_str));
575	        let output = self.runner.run("git", &args, &self.root)?;
576	        if !output.success() {
577	            // The batch exits 128 for a missing ref and for a broken repository alike; one probe each tells them apart.
578	            for r in refs {
579	                if self.resolve_commit(r)?.is_none() {
580	                    return Ok(None);
581	                }
582	            }
583	            return Err(probe_failed(&args, &self.root, &output));
584	        }
585	        let shas: Option<Vec<CommitSha>> = output.stdout_lines().map(|l| CommitSha::parse(l).ok()).collect();
586	        Ok(shas.filter(|shas| shas.len() == refs.len()))
587	    }
588	
589	    /// Paths, relative to the root and limited to it, that non-merge commits
590	    /// in `since_ref..HEAD` touched. Selects exactly what
591	    /// [`Self::commits_since`] filters on: `--full-history`, and a rename
592	    /// counts for both its old and new path.
593	    pub fn paths_changed_since(&self, since_ref: &str) -> Result<Vec<PathBuf>, VcsError> {
594	        let range = format!("{since_ref}..HEAD");
595	        self.name_only(&[
596	            "log",
597	            "--no-merges",
598	            "--full-history",
599	            "--no-renames",
600	            "--relative",
601	            "--name-only",
602	            "-z",
603	            "--format=",
604	            &range,
605	            "--",
606	        ])
607	    }
608	
609	    /// Tracked paths, relative to the root and limited to it, whose worktree
610	    /// contents differ from `since_ref`.
611	    pub fn paths_differing_from(&self, since_ref: &str) -> Result<Vec<PathBuf>, VcsError> {
612	        self.name_only(&[
613	            "diff",
614	            "--no-renames",
615	            "--relative",
616	            "--name-only",
617	            "-z",
618	            since_ref,
619	            "--",
620	        ])
621	    }
622	
623	    fn name_only(&self, args: &[&str]) -> Result<Vec<PathBuf>, VcsError> {
624	        let output = self.runner.run("git", args, &self.root)?;
625	        if !output.success() {
626	            return Err(VcsError::Git(format!(
627	                "`git {}` failed in `{}`: {}",
628	                args[0],
629	                self.root.display(),
630	                output.redacted_stderr()
631	            )));
632	        }
633	        Ok(output
634	            .stdout
635	            .split('\0')
636	            .map(|path| path.trim_start_matches('\n'))
637	            .filter(|path| !path.is_empty())
638	            .map(PathBuf::from)
639	            .collect())
640	    }
641	
642	    /// Creates the tag `name` at `target_sha`: annotated with `message`
643	    /// when `Some`, lightweight when `None`. Fails if the tag already
644	    /// exists. Writes a ref, so it requires an [`ApplyPermit`].
645	    pub fn create_tag(
646	        &self,
647	        name: &str,
648	        target_sha: &CommitSha,
649	        message: Option<&str>,
650	        sign: TagSignPolicy,
651	        _permit: &ApplyPermit,
652	    ) -> Result<(), VcsError> {
653	        let identity = match message {
654	            Some(_) => self.tagger_identity_override(target_sha)?,
655	            None => None,
656	        };
657	        let mut args: Vec<&str> = Vec::new();
658	        if let Some([name_config, email_config]) = &identity {
659	            args.extend(["-c", name_config.as_str(), "-c", email_config.as_str()]);
660	        }
661	        // `--` ends option parsing so `name` can never be misread as a flag.
662	        args.push("tag");
663	        if let Some(msg) = message {
664	            args.extend(["-a", "-m", msg]);
665	        }
666	        if matches!(sign, TagSignPolicy::ForceUnsigned) {
667	            args.push("--no-sign");
668	        }
669	        args.extend(["--", name, target_sha.as_str()]);

