317	/// One operation role's adapter: what it can do, what it sees, what it does.
318	pub(crate) trait ReleaseProvider {
319	    fn capabilities(&self) -> ProviderCapabilities;
320	
321	    fn observe(
322	        &self,
323	        context: &ProviderContext<'_>,
324	        request: &ProviderRequest<'_>,
325	    ) -> Result<ProviderObservationV1, GraphError>;
326	
327	    /// Issues the one mutating action, then re-observes: the returned evidence
328	    /// is always a post-effect observation, never the client's own exit code.
329	    fn publish(
330	        &self,
331	        context: &ProviderContext<'_>,
332	        request: &ProviderRequest<'_>,
333	        effect: &EffectAuthorization<'_>,
334	    ) -> Result<ExactEvidence, GraphError>;
335	
336	    /// Whether this operation is issued now and confirmed by a later [`Self::observe`].
337	    fn defers_confirmation(&self, _request: &ProviderRequest<'_>) -> bool {
338	        false
339	    }
340	
341	    /// [`Self::publish`] without the confirmation, for an operation that defers it.
342	    fn issue(
343	        &self,
344	        _context: &ProviderContext<'_>,
345	        request: &ProviderRequest<'_>,
346	        _effect: &EffectAuthorization<'_>,
347	    ) -> Result<(), GraphError> {
348	        Err(GraphError::ReleaseInvariant {
349	            detail: format!("`{}` does not defer its confirmation", request.id),
350	        })
351	    }
352	
353	    /// How long the provider may take to show an issued effect.
354	    fn confirmation_window(&self, _request: &ProviderRequest<'_>) -> Duration {
355	        Duration::ZERO
356	    }
357	
358	    /// The disagreement this role reports when a pre-effect observation is
359	    /// neither absent nor exactly the intended result.
360	    fn preflight_conflict(&self) -> RemoteConflict;
361	
362	    fn preflight(
363	        &self,
364	        context: &ProviderContext<'_>,
365	        request: &ProviderRequest<'_>,
366	    ) -> Result<ReleasePreflight, GraphError> {
367	        preflight_from_observation(self.observe(context, request)?, request.id, self.preflight_conflict())
368	    }
369	}
