371	/// The one place a prepared operation is routed to the provider that performs
372	/// it. Roles are selected here; the registry role selects its per-ecosystem
373	/// adapter in [`registry::adapter_for`], which is the only other selection.
374	fn provider_for(operation: &PreparedOperation) -> &'static dyn ReleaseProvider {
375	    match operation {
376	        PreparedOperation::RegistryPublish(_) => &registry::RegistryProvider,
377	        PreparedOperation::Tag(_) => &tag::TagProvider,
378	        PreparedOperation::ForgeRelease(_) => &forge::ForgeReleaseProvider,
379	        PreparedOperation::ArtifactUpload(_) => &artifact::ArtifactUploadProvider,
380	        PreparedOperation::ForgePublish(_) => &forge::ForgePublishProvider,
381	    }
382	}
383	
384	/// A role that can issue an effect but cannot be asked what the provider holds
385	/// could never prove absence before acting, so it is refused here -- before any
386	/// observation or effect -- rather than at dispatch.
387	pub(crate) fn checked_provider_for(operation: &PreparedOperation) -> Result<&'static dyn ReleaseProvider, GraphError> {
388	    let provider = provider_for(operation);
389	    require_observable(provider.capabilities())?;
390	    Ok(provider)
391	}
392	
393	fn require_observable(capabilities: ProviderCapabilities) -> Result<(), GraphError> {
394	    if capabilities.can_publish && !capabilities.can_observe {
395	        return Err(GraphError::ReleasePreconditionUnmet {
396	            requirement: ReleasePreconditionRequirement::ObservableProvider,
397	        });
398	    }
399	    Ok(())
400	}
401	
402	/// Maps one observation to its pre-effect decision. `conflict` names the
403	/// operation-specific disagreement so the typed error stays precise.
404	pub(crate) fn preflight_from_observation(
405	    observation: ProviderObservationV1,
406	    id: &ReleaseOperationId,
407	    conflict: RemoteConflict,
408	) -> Result<ReleasePreflight, GraphError> {
409	    match &observation {
410	        ProviderObservationV1::Absent => Ok(ReleasePreflight::Proceed {
411	            proof: observation
412	                .absent_proof()
413	                .expect("an absent observation mints an absent proof"),
414	        }),
415	        ProviderObservationV1::Exact { .. } => Ok(ReleasePreflight::AlreadySatisfied {
416	            evidence: observation
417	                .exact_evidence()
418	                .expect("an exact observation mints its evidence"),
419	        }),
420	        ProviderObservationV1::Conflict { .. } => Err(GraphError::ReleaseRemoteConflict { conflict }),
421	        ProviderObservationV1::Indeterminate { cause } => Err(GraphError::ReleaseProviderIndeterminate {
422	            operation: Box::new(id.clone()),
423	            cause: *cause,
424	        }),
425	    }
426	}
427	
428	/// Requires that a post-effect observation is exact before the operation may
429	/// be recorded as done.
430	pub(crate) fn confirmed_evidence(
431	    observation: ProviderObservationV1,
432	    id: &ReleaseOperationId,
433	    conflict: RemoteConflict,
434	) -> Result<ExactEvidence, GraphError> {
435	    match &observation {
436	        ProviderObservationV1::Exact { .. } => Ok(observation
437	            .exact_evidence()
438	            .expect("an exact observation mints its evidence")),
439	        ProviderObservationV1::Indeterminate { cause } => Err(GraphError::ReleaseProviderIndeterminate {
440	            operation: Box::new(id.clone()),
441	            cause: *cause,
442	        }),
443	        ProviderObservationV1::Absent | ProviderObservationV1::Conflict { .. } => {
444	            Err(GraphError::ReleaseRemoteConflict { conflict })
445	        }
446	    }
447	}
448	
449	/// The invariant error a provider raises when it is handed another role's
450	/// prepared operation.
451	pub(crate) fn wrong_role(id: &ReleaseOperationId, expected: &str) -> GraphError {
452	    GraphError::ReleaseInvariant {
453	        detail: format!("operation `{id:?}` is not a prepared {expected} operation"),
454	    }
455	}
