/// The invocation data for one effect. This is deliberately graph-private:
/// callers can inspect the serializable intent, but cannot substitute a new
/// endpoint, tag target, or package directory at execution time.
#[derive(Debug)]
pub(crate) enum PreparedOperation {
    RegistryPublish(RegistryPublishOperation),
    Tag(TagOperation),
    ForgeRelease(ForgeReleaseOperation),
    ArtifactUpload(ArtifactUploadOperation),
    ForgePublish(ForgePublishOperation),
}

#[derive(Debug)]
pub(crate) struct RegistryPublishOperation {
    pub(crate) package_dir: PathBuf,
    pub(crate) package_name: String,
    pub(crate) version: Version,
    pub(crate) registry: PreparedRegistryBinding,
    pub(crate) npm_access: Option<NpmAccess>,
    pub(crate) npm_tag: Option<String>,
    /// Publish `package_dir` by path rather than selecting a workspace member by name.
    pub(crate) by_directory: bool,
}

#[derive(Debug)]
pub(crate) struct TagOperation {
    pub(crate) name: TagName,
    pub(crate) target: CommitSha,
    pub(crate) annotation: String,
}

#[derive(Debug)]
pub(crate) struct ForgeReleaseOperation {
    pub(crate) tag: TagName,
    pub(crate) prerelease: bool,
    /// Derived from the changelog at execution; not part of the intent digest.
    pub(crate) notes: ReleaseNotes,
}

/// The body a forge release is created with.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) enum ReleaseNotes {
    /// The package's changelog section for the released version.
    Section(String),
    /// The forge generates notes, because no changelog section is usable.
    Generated { reason: NotesFallback },
}

/// Why a forge release falls back to generated notes.
#[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error)]
pub(crate) enum NotesFallback {
    #[error("no changelog configured")]
    NotConfigured,
    #[error("changelog file missing")]
    FileMissing,
    #[error("no section for this version")]
    SectionMissing,
    #[error("changelog section is empty")]
    SectionEmpty,
}

