224	/// One ecosystem's registry client. This is the single place the release path
225	/// branches on [`Ecosystem`]: adding a registry means adding an adapter here,
226	/// not another match in preflight, dispatch, or confirmation.
227	pub(crate) trait RegistryEcosystem {
228	    fn ecosystem(&self) -> Ecosystem;
229	
230	    /// Whether a publish here is complete once the version is visible, so the run can issue the next publish while
231	    /// this one propagates. Not true where completion is more than visibility: PyPI compares a whole file set.
232	    fn defers_confirmation(&self) -> bool {
233	        false
234	    }
235	
236	    /// The repository the registry says this published version belongs to. Best effort: a registry that records
237	    /// none, or a read that fails, is `None`.
238	    fn repository(&self, _context: &ProviderContext<'_>, _operation: &RegistryPublishOperation) -> Option<String> {
239	        None
240	    }
241	
242	    /// Whether this registry exposes a query that proves an exact published
243	    /// version. `false` makes every observation `Indeterminate`, so a publish
244	    /// is never confirmed here and instead fails closed at the mandatory
245	    /// post-effect exact observation.
246	    fn can_observe_versions(&self) -> bool;
247	
248	    /// One observation attempt. Only called when [`Self::can_observe_versions`].
249	    fn observe_once(
250	        &self,
251	        context: &ProviderContext<'_>,
252	        operation: &RegistryPublishOperation,
253	    ) -> Result<Attempt<ProviderObservationV1>, GraphError>;
254	
255	    /// Runs the publish client and returns the output that decides the outcome.
256	    fn publish(
257	        &self,
258	        context: &ProviderContext<'_>,
259	        id: &ReleaseOperationId,
260	        operation: &RegistryPublishOperation,
261	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
262	    ) -> Result<CommandOutput, GraphError>;
263	
264	    fn classify(&self, output: &CommandOutput) -> Result<PublishOutcome, RegistryError>;
265	
266	    /// What the one fresh pre-effect observation authorizes.
267	    fn preflight(
268	        &self,
269	        context: &ProviderContext<'_>,
270	        id: &ReleaseOperationId,
271	        operation: &RegistryPublishOperation,
272	        _artifacts: Option<&VerifiedArtifactManifest<'_>>,
273	    ) -> Result<ReleasePreflight, GraphError> {
274	        match registry_observation(self, context, operation)? {
275	            // A registry with no query API at all has nothing to observe
276	            // before the effect; the post-effect confirmation fails closed.
277	            ProviderObservationV1::Indeterminate {
278	                cause: ProviderIndeterminateCause::UnsupportedProvider,
279	            } => Ok(proceed()),
280	            observation => preflight_from_observation(observation, id, RemoteConflict::RegistryVersionDiffers),
281	        }
282	    }
283	
284	    /// The observation that lets a finished publish be recorded. The client reported the version published or already
285	    /// there, so a registry that does not show it yet is lagging, and is waited on.
286	    fn confirm(
287	        &self,
288	        context: &ProviderContext<'_>,
289	        _id: &ReleaseOperationId,
290	        operation: &RegistryPublishOperation,
291	        _artifacts: Option<&VerifiedArtifactManifest<'_>>,
292	    ) -> Result<ProviderObservationV1, GraphError> {
293	        if self.can_observe_versions() {
294	            confirmed_registry_observation(self, context, operation)
295	        } else {
296	            registry_observation(self, context, operation)
297	        }
298	    }
299	}
