430	/// The name the *cargo* client knows this registry by. Callisto's logical
431	/// `cratesIo` key is cargo's built-in `crates-io`; every other key is spelled
432	/// the same in `.cargo/config.toml` as it is in `callisto.toml`.
433	/// The cargo registry name for a logical registry key (`cratesIo` is cargo's `crates-io`).
434	pub fn cargo_registry_name(key: &RegistryKey) -> &str {
