442	/// The observation argv: `cargo info NAME@VERSION --registry REGISTRY`.
443	///
444	/// `--registry` is never omitted. Without it `cargo info` resolves the local
445	/// workspace and reports an unpublished member's on-disk version as published
446	/// (`version: X (from ./)`), which is the defect this observation exists to
447	/// avoid; with it, cargo reads only the named registry.
448	///
449	/// `net.retry=0` must precede `info` (cargo ignores it after the subcommand):
450	/// callisto's bounded retry owns retrying, and cargo's own backoff inside each
451	/// attempt made an unreachable registry take ~11s per attempt.
452	fn cargo_info_args<'a>(spec: &'a str, registry: &'a str) -> [&'a str; 6] {
453	    ["--config", "net.retry=0", "info", spec, "--registry", registry]
454	}
