536	/// Classifies one real `cargo info` run. There is no `--json`, so the two
537	/// answers cargo actually proves are read from its exit code and its text:
538	///
539	/// - exit 0 with a `version: VERSION` line for the requested version: `Exact`.
540	///   `cargo info` reports neither the index checksum nor the yank flag, so the
541	///   evidence says `None` for both rather than inventing them.
542	/// - exit 101 with ``could not find `NAME@VERSION` ``: `Absent`.
543	/// - anything else -- another exit code, another message (a network failure
544	///   prints ``failed to load source for dependency``), or a zero exit with no
545	///   matching version line: transient `Indeterminate`, retried by the bounded
546	///   policy. An unreachable registry must never read as an absence.
547	///
548	/// A *yanked* version reads as `Absent`, because `cargo info` cannot see yanks
549	/// and answers "could not find" for one. That fails closed rather than open:
550	/// the publish attempt that follows is refused by the registry, and since only
551	/// an `Exact` observation may satisfy an operation, the run ends in the typed
552	/// `RegistryPublishUnconfirmed` error instead of a receipt.
553	fn classify_cargo_info(output: &CommandOutput, spec: &str, version: &Version) -> Attempt<ProviderObservationV1> {
554	    if output.success() {
555	        return if reports_version(&output.stdout, version) {
556	            settled(ProviderObservationV1::Exact {
557	                evidence: ProviderEvidenceV1::RegistryVersion {
558	                    version: version.clone(),
559	                    checksum: None,
560	                    yanked: None,
561	                },
562	            })
563	        } else {
564	            transient(ProviderIndeterminateCause::MalformedResponse, None)
565	        };
566	    }
567	    if output.exit_code == Some(101) && output.stderr.contains(&format!("could not find `{spec}`")) {
568	        return settled(ProviderObservationV1::Absent);
569	    }
570	    transient(ProviderIndeterminateCause::CommandFailed, None)
571	}
572	
573	/// The value of the `repository:` line `cargo info` prints, if the crate has one.
574	fn cargo_info_repository(stdout: &str) -> Option<String> {
575	    stdout
576	        .lines()
577	        .find_map(|line| line.trim().strip_prefix("repository:"))
578	        .map(|value| value.trim().to_owned())
579	        .filter(|value| !value.is_empty())
580	}
581	
582	/// Whether cargo's `version: X ...` line names exactly the requested version.
583	fn reports_version(stdout: &str, version: &Version) -> bool {
584	    stdout.lines().any(|line| {
585	        line.trim()
586	            .strip_prefix("version: ")
587	            .and_then(|rest| rest.strip_prefix(version.render()))
588	            .is_some_and(|rest| rest.is_empty() || rest.starts_with(char::is_whitespace))
589	    })
590	}
