592	/// The code npm gives a registry 404 for a package or a version.
593	const NPM_NOT_FOUND_CODE: &str = "E404";
594	
595	/// Only npm's own `E404` code proves absence, never text around it; any other failure is a retried `CommandFailed`.
596	fn classify_npm_view(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
597	    if output.success() {
598	        return if output.stdout_trimmed().is_empty() {
599	            transient(ProviderIndeterminateCause::MalformedResponse, None)
600	        } else {
601	            settled(ProviderObservationV1::Exact {
602	                evidence: ProviderEvidenceV1::RegistryVersion {
603	                    version: version.clone(),
604	                    checksum: None,
605	                    yanked: None,
606	                },
607	            })
608	        };
609	    }
610	    let code = if output.stdout_trimmed().is_empty() {
611	        npm_stderr_code(&output.stderr)
612	    } else {
613	        npm_error_code(&output.stdout)
614	    };
615	    if code.as_deref() == Some(NPM_NOT_FOUND_CODE) {
616	        return settled(ProviderObservationV1::Absent);
617	    }
618	    transient(ProviderIndeterminateCause::CommandFailed, None)
619	}
