621	/// The repository URL in `npm view <spec> repository --json`: a string, or an object with a `url`.
622	fn npm_view_repository(stdout: &str) -> Option<String> {
623	    let value: serde_json::Value = serde_json::from_str(stdout.trim()).ok()?;
624	    match value {
625	        serde_json::Value::String(url) => Some(url),
626	        serde_json::Value::Object(map) => map.get("url")?.as_str().map(str::to_owned),
627	        _ => None,
628	    }
629	    .filter(|url| !url.is_empty())
630	}
631	
632	/// The `error.code` of the JSON error body `npm --json` prints to stdout on failure.
633	fn npm_error_code(stdout: &str) -> Option<String> {
634	    let body: serde_json::Value = serde_json::from_str(stdout.trim()).ok()?;
635	    body.get("error")?.get("code")?.as_str().map(str::to_owned)
636	}
637	
638	/// The code on npm's `npm ERR! code X` or `npm error code X` stderr line; npm 8 prints no JSON body.
639	fn npm_stderr_code(stderr: &str) -> Option<String> {
640	    stderr.lines().find_map(|line| {
641	        let rest = line
642	            .strip_prefix("npm ERR! ")
643	            .or_else(|| line.strip_prefix("npm error "))?;
644	        rest.strip_prefix("code ").map(|code| code.trim().to_owned())
645	    })
646	}
