757	struct PypiRegistry;
758	
759	/// PyPI's own PEP 691 JSON simple index, not `pip`: `pip index versions` is
760	/// experimental and hides yanked releases, and an unreachable index and a
761	/// missing project both look like "no versions found" to it. The index itself
762	/// answers plainly -- 200 with a `files[]` entry naming the version, or 404 --
763	/// so observation goes straight to `https://pypi.org/simple/<project>/`
764	/// (or the configured private index) over `curl`, never through `pip`.
765	const PYPI_DEFAULT_SIMPLE_INDEX: &str = "https://pypi.org/simple";
766	
767	/// PEP 691: the versioned JSON media type, so the index cannot fall back to
768	/// the legacy HTML page a bare GET would otherwise serve.
769	const PYPI_SIMPLE_ACCEPT: &str = "application/vnd.pypi.simple.v1+json";
770	
771	/// The project's simple-index URL: the configured private index if one is
772	/// bound (already https-validated in `binding.rs`), else the public default.
773	fn pypi_simple_index_url(endpoint: Option<&str>, package_name: &str) -> String {
774	    let base = endpoint.unwrap_or(PYPI_DEFAULT_SIMPLE_INDEX);
775	    let project = normalize_pypi_project_name(package_name);
776	    format!("{}/{project}/", base.trim_end_matches('/'))
777	}
778	
779	/// The version segment of a simple-index filename, or `None` for an extension
780	/// this parser does not recognize (a legacy installer, say).
781	fn pypi_simple_file_version(filename: &str) -> Option<&str> {
782	    callisto_model::pypi_dist_filename_parts(filename).map(|(_, version)| version)
783	}
784	
785	/// Whether a simple-index file's filename names exactly the requested version.
786	fn pypi_simple_file_matches(file: &PypiSimpleFile, version: &Version) -> bool {
787	    pypi_simple_file_version(&file.filename).is_some_and(|candidate| {
788	        Version::parse(candidate, version.grammar())
789	            .is_ok_and(|candidate| candidate.compare(version) == Ok(std::cmp::Ordering::Equal))
790	    })
791	}
792	
793	/// Classifies a parsed 200 body: the matching file's yank status decides the
794	/// answer, mirroring cargo's yanked-is-absent rationale above -- a yanked
795	/// release is not the version this intent authorized, so it fails closed.
796	fn classify_pypi_simple_body(body: &str, version: &Version) -> Attempt<ProviderObservationV1> {
797	    let Ok(index) = serde_json::from_str::<PypiSimpleIndex>(body) else {
798	        return transient(ProviderIndeterminateCause::MalformedResponse, None);
799	    };
800	    let matching = index
801	        .files
802	        .iter()
803	        .filter(|file| pypi_simple_file_matches(file, version));
804	    let mut matched = false;
805	    for file in matching {
806	        if file.is_yanked() {
807	            return settled(ProviderObservationV1::Absent);
808	        }
809	        matched = true;
810	    }
811	    if !matched {
812	        return settled(ProviderObservationV1::Absent);
813	    }
814	    settled(exact_version(version))
815	}
816	
817	/// The observation that a version is on the registry, unyanked.
818	fn exact_version(version: &Version) -> ProviderObservationV1 {
819	    ProviderObservationV1::Exact {
820	        evidence: ProviderEvidenceV1::RegistryVersion {
821	            version: version.clone(),
822	            checksum: None,
823	            yanked: Some(false),
824	        },
825	    }
826	}
827	
828	/// What the index holds for one release.
829	enum PypiRemote {
830	    Absent,
831	    Files(Vec<PypiSimpleFile>),
832	    Indeterminate(ProviderIndeterminateCause),
833	}
834	
835	/// The release's own files from a parsed 200 body.
836	fn classify_pypi_files_body(body: &str, version: &Version) -> Attempt<PypiRemote> {
837	    let Ok(index) = serde_json::from_str::<PypiSimpleIndex>(body) else {
838	        return Attempt::Transient {
839	            value: PypiRemote::Indeterminate(ProviderIndeterminateCause::MalformedResponse),
840	            retry_after: None,
841	        };
842	    };
843	    let files: Vec<_> = index
844	        .files
845	        .into_iter()
846	        .filter(|file| pypi_simple_file_matches(file, version))
847	        .collect();
848	    Attempt::Settled(if files.is_empty() {
849	        PypiRemote::Absent
850	    } else {
851	        PypiRemote::Files(files)
852	    })
853	}
854	
855	/// Classifies one `curl -sS -i` run against the simple index. A private index
856	/// that ignores `Accept` and serves its legacy HTML page fails the JSON parse
857	/// inside `on_ok` and reads as `MalformedResponse`, same as any other body PEP
858	/// 691 JSON parsing cannot make sense of.
859	///
860	/// Any other status shares [`HttpResponse::is_transient`] with GitHub's `gh api` reads, so it retries on
861	/// `Retry-After` instead of settling immediately, and either way reports the status as `ProviderStatus`.
862	fn classify_pypi_status<T>(
863	    output: &CommandOutput,
864	    on_ok: impl FnOnce(&str) -> Attempt<T>,
865	    absent: T,
866	    indeterminate: impl Fn(ProviderIndeterminateCause) -> T,
867	) -> Attempt<T> {
868	    let response = match parse_http_response(&output.stdout) {
869	        Ok(response) => response,
870	        Err(_) if !output.success() => {
871	            return Attempt::Transient {
872	                value: indeterminate(ProviderIndeterminateCause::CommandFailed),
873	                retry_after: None,
874	            }
875	        }
876	        Err(_) => {
877	            return Attempt::Transient {
878	                value: indeterminate(ProviderIndeterminateCause::MalformedResponse),
879	                retry_after: None,
880	            }
881	        }
882	    };
883	    match response.status {
884	        200 => on_ok(&response.body),
885	        404 => Attempt::Settled(absent),
886	        status if response.is_transient() => Attempt::Transient {
887	            value: indeterminate(ProviderIndeterminateCause::ProviderStatus { status }),
888	            retry_after: response.retry_after(),
889	        },
890	        status => Attempt::Settled(indeterminate(ProviderIndeterminateCause::ProviderStatus { status })),
891	    }
892	}
893	
894	fn classify_pypi_simple(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
895	    classify_pypi_status(
896	        output,
897	        |body| classify_pypi_simple_body(body, version),
898	        ProviderObservationV1::Absent,
899	        |cause| ProviderObservationV1::Indeterminate { cause },
900	    )
901	}
902	
903	fn classify_pypi_files(output: &CommandOutput, version: &Version) -> Attempt<PypiRemote> {
904	    classify_pypi_status(
905	        output,
906	        |body| classify_pypi_files_body(body, version),
907	        PypiRemote::Absent,
908	        PypiRemote::Indeterminate,
909	    )
910	}
