1139:    fn classify_twine_output_a_failing_run_is_never_already_published() {
1140-        let out = output(1, "", "HTTPError: 400 File already exists");
1141-        assert!(matches!(classify_twine_output(&out), Err(RegistryError::Other(_))));
1142-    }
1143-
1144-    /// Without `--skip-existing` (private index, or a race against the
1145-    /// preflight observation), a real conflict is a typed error, not a
1146-    /// guessed `AlreadyPublished` -- captured verbatim from a real
1147-    /// `pypiserver` 409 response, which carries no "already exist" text.
1148-    #[test]
1149:    fn classify_twine_output_private_index_conflict_without_skip_existing_is_a_typed_error() {
1150-        let out = output(1, "", "HTTPError: 409 Conflict from http://127.0.0.1:18081/\nConflict");
