20	/// What the local repository holds at `refs/tags/<name>`; identity is the target commit plus being annotated.
21	#[derive(Debug, PartialEq, Eq)]
22	enum LocalTagObservation {
23	    Absent,
24	    Annotated {
25	        target: CommitSha,
26	    },
27	    /// A lightweight tag, or any other object this adapter did not write.
28	    Unannotated,
29	}
30	
31	/// What the prepared remote holds at `refs/tags/<name>`. `ls-remote` cannot
32	/// read annotation text, so only the tagged commit is comparable.
33	#[derive(Debug, PartialEq, Eq)]
34	enum RemoteTagObservation {
35	    Absent,
36	    Annotated { target: CommitSha },
37	    Unannotated,
38	    Indeterminate,
39	}
