1	//! Canonical, credential-free registry and Git destinations.
2	//!
3	//! Every release effect is routed through a binding produced here, so no
4	//! caller-supplied endpoint or credential can reach a provider.
5	
6	use std::path::Path;
7	
8	use callisto_model::{
9	    CanonicalTranscript, CommandRunner, Ecosystem, GitHubRepository, GitHubRepositoryParseError, PackageId,
10	    PublishTarget, RegistryBindingDigest, RegistryKey, SemanticInputDigest,
11	};
12	
13	use crate::registry_endpoint::{
14	    builtin_registry_url, canonical_registry_url, split_routes_digest, url_parse_error_reason, RegistryBindingV1,
15	};
16	use crate::{DependencyResolver, GraphError, Workspace};
17	
18	use super::provider::policy::{programs, timeouts};
19	use super::StaleReason;
20	
21	/// Credential-free, canonical registry routing. `endpoint` is populated only
22	/// after parsing rejects userinfo, query, and fragments, so a later executor
23	/// cannot recover credentials from this capability.
24	#[derive(Debug)]
25	pub(crate) struct PreparedRegistryBinding {
26	    pub(crate) key: RegistryKey,
27	    pub(crate) endpoint: Option<String>,
28	    /// Where uploads go when that differs from `endpoint` (a PyPI index that is not also its upload route).
29	    pub(crate) publish_endpoint: Option<String>,
30	    pub(crate) identity: RegistryBindingDigest,
31	    /// How long a version this run published may take to appear; execution policy, so not part of `identity`.
32	    pub(crate) confirm_timeout: Option<std::time::Duration>,
33	    /// The longest one publish command may run; execution policy, so not part of `identity`.
34	    pub(crate) publish_timeout: Option<std::time::Duration>,
35	}
36	
37	impl PreparedRegistryBinding {
38	    /// The endpoint an upload is sent to: the separate upload route if one is bound, else the index.
39	    pub(crate) fn upload_endpoint(&self) -> Option<&str> {
40	        self.publish_endpoint.as_deref().or(self.endpoint.as_deref())
41	    }
42	}
43	
44	/// Immutable, credential-free destination for Git effects. Its canonical
45	/// digest is included in each tag-producing package fingerprint; the URL is
46	/// retained only in the validated, non-serializable capability.
47	#[derive(Clone, Debug, PartialEq, Eq)]
48	pub(crate) struct PreparedGitRemote {
49	    pub(crate) endpoint: String,
50	    pub(crate) identity: SemanticInputDigest,
51	    pub(crate) github_repository: Option<GitHubRepository>,
52	}
53	
54	/// The single registry-trust validator: resolves `target`'s own registry key, rejects a
55	/// non-https or credentialed URL, and rejects an npm `publishConfig.registry` override (package-
56	/// controlled data) unless it matches a `url` on an npm-kind `[registries]` entry.
57	pub(crate) fn prepared_registry_binding<R: CommandRunner, D: DependencyResolver>(
58	    workspace: &Workspace<'_, R, D>,
59	    target: &PublishTarget,
60	    package: &PackageId,
61	) -> Result<PreparedRegistryBinding, GraphError> {
62	    let key = target.registry_key().ok_or_else(|| GraphError::ReleaseInvariant {
63	        detail: format!("publish target `{}` has no registry key", target.config_str()),
64	    })?;
65	    // Built-in keys (pypi, nuget) need no [registries] entry; an unknown key still fails.
66	    let builtin_unconfigured = builtin_registry_url(key.as_str()).is_some();
67	    let configured_registry = match workspace.config.registries.get(&key) {
68	        Some(registry) => Some(registry),
69	        None if builtin_unconfigured => None,
70	        None => {
71	            return Err(GraphError::ReleaseInvariant {
72	                detail: format!("unknown registry `{}`", key.as_str()),
73	            })
74	        }
75	    };
76	    if let Some(registry) = configured_registry.filter(|registry| Some(registry.kind) != target.ecosystem()) {
77	        return Err(GraphError::ReleaseInvariant {
78	            detail: format!(
79	                "registry `{}` is configured for ecosystem `{}`, not `{}`",
80	                key.as_str(),
81	                registry.kind.prefix(),
82	                target.ecosystem().map_or("none", |ecosystem| ecosystem.prefix())
83	            ),
84	        });
85	    }
86	    let explicit = target.registry_override();
87	    let configured = configured_registry.and_then(|registry| registry.url.as_deref());
88	    // An explicit per-package index names both routes, so the registry entry's upload route does not apply.
89	    let publish_raw = match explicit {
90	        Some(_) => None,
91	        None => configured_registry.and_then(|registry| registry.publish_url.as_deref()),
92	    };
93	    let raw = explicit.or(configured);
94	    let index = raw
95	        .map(|raw| canonical_registry_binding(key.as_str(), raw))
96	        .transpose()?;
97	    let publish = publish_raw
98	        .map(|raw| canonical_registry_binding(key.as_str(), raw))
99	        .transpose()?;
100	    if let (Some(raw), Some(binding)) = (explicit, &index)
101	        && matches!(target, PublishTarget::Npm { .. })
102	        && !is_approved_npm_registry(workspace, binding)
103	    {
104	        return Err(GraphError::UntrustedNpmRegistry {
105	            package: package.clone(),
106	            url: raw.to_owned(),
107	        });
108	    }
109	    let identity = match (&index, &publish) {
110	        (_, Some(publish)) => split_routes_digest(index.as_ref(), publish),
111	        (Some(index), None) => index.digest(),
112	        (None, None) => RegistryBindingDigest::from_normalized_binding(key.as_str().as_bytes()),
113	    };
114	    Ok(PreparedRegistryBinding {
115	        key,
116	        endpoint: index.as_ref().map(RegistryBindingV1::endpoint),
117	        publish_endpoint: publish.as_ref().map(RegistryBindingV1::endpoint),
118	        identity,
119	        confirm_timeout: configured_registry.and_then(|registry| registry.confirm_timeout),
120	        publish_timeout: configured_registry.and_then(|registry| registry.publish_timeout),
121	    })
122	}
123	
124	fn is_approved_npm_registry<R: CommandRunner, D: DependencyResolver>(
125	    workspace: &Workspace<'_, R, D>,
126	    binding: &RegistryBindingV1,
127	) -> bool {
128	    workspace.config.registries.values().any(|registry| {
129	        registry.kind == Ecosystem::Npm
130	            && registry
131	                .url
132	                .as_deref()
133	                .and_then(|url| canonical_registry_url(url).ok())
134	                .is_some_and(|approved| approved == *binding)
135	    })
136	}
137	
138	pub(crate) fn canonical_registry_binding(registry: &str, raw: &str) -> Result<RegistryBindingV1, GraphError> {
139	    canonical_registry_url(raw).map_err(|reason| GraphError::UnsafeRegistryBinding {
140	        registry: registry.to_string(),
141	        reason,
142	    })
143	}
144	
145	/// Maps a [`GitHubRepositoryParseError`] to a specific, static diagnostic
146	/// reason for [`GraphError::UnsafeGitRemote`], rather than discarding it
147	/// behind one generic message for every distinct parse failure.
148	fn github_repository_parse_error_reason(error: &GitHubRepositoryParseError) -> &'static str {
149	    match error {
150	        GitHubRepositoryParseError::MissingSeparator { .. } => "GitHub remote path must be in owner/repo form",
151	        GitHubRepositoryParseError::TooManyParts { .. } => "GitHub remote path has more than one `/`",
152	        GitHubRepositoryParseError::InvalidOwner { .. } => "GitHub owner name is invalid",
153	        GitHubRepositoryParseError::InvalidRepo { .. } => "GitHub repository name is invalid",
154	        GitHubRepositoryParseError::DotComponent { .. } => "GitHub owner or repository is a dot component",
155	        #[allow(unreachable_patterns)]
156	        _ => "GitHub owner or repository name is invalid",
157	    }
158	}
159	
160	pub(crate) fn prepared_git_remote(root: &Path, runner: &dyn CommandRunner) -> Result<PreparedGitRemote, GraphError> {
161	    // A missing/unset `origin` is an answer this call interprets itself (into
162	    // `UnsafeGitRemote`), not an unexpected failure worth echoing git's own
163	    // "No such remote" to the terminal -- so this is a quiet probe.
164	    let output = runner.run_quiet(
165	        programs::GIT,
166	        &["remote", "get-url", "--push", programs::GIT_REMOTE],
167	        root,
168	        timeouts::LOCAL_GIT,
169	    )?;
170	    if output.exit_code != Some(0) {
171	        return Err(GraphError::UnsafeGitRemote {
172	            reason: "origin must have a push URL",
173	        });
174	    }
175	    canonical_git_remote(output.stdout.trim())
176	}
177	
178	/// `origin`'s canonical push URL, or `None` when `origin` has no push URL.
179	pub(crate) fn optional_git_remote(
180	    root: &Path,
181	    runner: &dyn CommandRunner,
182	) -> Result<Option<PreparedGitRemote>, GraphError> {
183	    // A repository with no `origin` is an expected, common case here (e.g.
184	    // before `init` adds one), not a failure -- probe quietly so git's own
185	    // "error: No such remote 'origin'" never reaches the terminal.
186	    let output = runner.run_quiet(
187	        programs::GIT,
188	        &["remote", "get-url", "--push", programs::GIT_REMOTE],
189	        root,
190	        timeouts::LOCAL_GIT,
191	    )?;
192	    if output.exit_code != Some(0) {
193	        return Ok(None);
194	    }
195	    canonical_git_remote(output.stdout.trim()).map(Some)
196	}
197	
198	/// Re-reads `origin`'s push URL and refuses unless it is still exactly the
199	/// remote the intent was validated against.
200	pub(crate) fn recheck_git_remote(
201	    root: &Path,
202	    runner: &dyn CommandRunner,
203	    expected: &PreparedGitRemote,
204	) -> Result<(), GraphError> {
205	    if prepared_git_remote(root, runner)? != *expected {
206	        return Err(GraphError::ReleaseIntentStale {
207	            reason: StaleReason::git_remote_changed(),
208	        });
209	    }
210	    Ok(())
211	}
212	
213	pub(crate) fn canonical_git_remote(raw: &str) -> Result<PreparedGitRemote, GraphError> {
214	    let ssh_url = if raw.starts_with("git@") && !raw.contains("//") {
215	        let (host, path) =
216	            raw.strip_prefix("git@")
217	                .and_then(|value| value.split_once(':'))
218	                .ok_or(GraphError::UnsafeGitRemote {
