71	/// where to surface them, since a re-derivation for integrity verification has no
72	/// use for them.
73	pub(crate) fn derive_release_intent<R: CommandRunner, D: DependencyResolver>(
74	    workspace: &Workspace<'_, R, D>,
75	    decision: &ReleaseDecisionV1,
76	    source: SourceIdentity,
77	    trust_profile: ExecutionTrustProfileV1,
78	    artifact_policy: Option<&ArtifactBuildPolicy>,
79	    remote: GitRemoteRequirement,
80	    diagnostics: &mut Vec<Diagnostic>,
81	) -> Result<ReleaseIntentV1, GraphError> {
82	    let (snapshot, operations, _, _, slots) =
83	        derive_release_inputs_with(workspace, decision, source, artifact_policy, remote, diagnostics)?;
84	    Ok(ReleaseIntentV1::new(
85	        decision.clone(),
86	        snapshot,
87	        trust_profile,
88	        operations,
89	        slots,
90	    )?)
91	}
