93	/// See [`derive_release_intent`] for `diagnostics`.
94	pub(crate) fn derive_release_intent_with_prepared<R: CommandRunner, D: DependencyResolver>(
95	    workspace: &Workspace<'_, R, D>,
96	    decision: &ReleaseDecisionV1,
97	    source: SourceIdentity,
98	    trust_profile: ExecutionTrustProfileV1,
99	    artifact_policy: Option<&ArtifactBuildPolicy>,
100	    diagnostics: &mut Vec<Diagnostic>,
101	) -> Result<(ReleaseIntentV1, PreparedDerivation), GraphError> {
