114	pub(crate) fn artifact_policy_from_intent(intent: &ReleaseIntentV1) -> Result<Option<ArtifactBuildPolicy>, GraphError> {
115	    let Some(first) = intent.artifact_slots.first() else {
116	        return Ok(None);
117	    };
118	    let policy = &first.attestation_policy;
119	    if intent
120	        .artifact_slots
121	        .iter()
122	        .any(|slot| slot.attestation_policy != *policy)
123	    {
124	        return Err(GraphError::ReleaseInvariant {
125	            detail: "release intent mixes artifact attestation policies".to_owned(),
126	        });
127	    }
128	    Ok(Some(ArtifactBuildPolicy {
129	        repository: policy.repository.clone(),
130	        workflow_path: policy.workflow_path.clone(),
131	        workflow_commit: policy.workflow_commit.clone(),
132	    }))
133	}
