152	/// The decision's packages, by release identity, and each package's release identities.
153	struct Selection<'w> {
154	    selected: BTreeMap<ReleasePackageId, (&'w callisto_model::Package, Version)>,
155	    package_ids: BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
156	    /// The first selected identity of each package in manifest order: it carries the package's shared effects.
157	    owners: BTreeMap<callisto_model::PackageId, ReleasePackageId>,
158	}
159	
160	type Owners = BTreeMap<callisto_model::PackageId, ReleasePackageId>;
161	
162	/// The selected identities that own their package's shared effects: one tag, forge release and upload set per package.
163	fn owned<'a, 'w>(
164	    selected: &'a BTreeMap<ReleasePackageId, (&'w callisto_model::Package, Version)>,
165	    owners: &'a Owners,
166	) -> impl Iterator<Item = (&'a ReleasePackageId, &'a (&'w callisto_model::Package, Version))> {
167	    selected
168	        .iter()
169	        .filter(move |(id, (package, _))| owners.get(&package.id) == Some(*id))
170	}
