334	/// A prerelease publishes under the tag its first identifier names (`1.0.0-beta.2` -> `beta`), `next` when that is not a
335	/// plain word, and never `latest`; a stable version takes the registry default.
336	fn npm_dist_tag(version: &Version) -> Option<String> {
337	    if !version.is_prerelease() {
338	        return None;
339	    }
340	    let prerelease = version.render().split_once('-').map_or("", |(_, rest)| rest);
341	    let label: String = prerelease
342	        .chars()
343	        .take_while(char::is_ascii_alphabetic)
344	        .collect::<String>()
345	        .to_ascii_lowercase();
346	    Some(if label.is_empty() || label == "latest" {
347	        "next".to_string()
348	    } else {
349	        label
350	    })
351	}
