353	/// One registry publish per package target, with its platform publishes, and each package's input fingerprint.
354	fn build_publish_leaves<R: CommandRunner, D: DependencyResolver>(
355	    workspace: &Workspace<'_, R, D>,
356	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
357	    git_remote: Option<&PreparedGitRemote>,
358	    package_inputs: &mut Vec<ReleasePackageInputV1>,
359	    ops: &mut Ops,
360	) -> Result<(), GraphError> {
361	    let Ops {
362	        operations,
363	        prepared,
364	        index: OpIndex {
365	            publishes_by_package,
366	            platforms_by_publish,
367	            ..
368	        },
369	    } = ops;
370	
371	    // First construct leaves so dependency prerequisites can refer only to
372	    // exact selected release identities, never PackageId's wildcard matcher.
373	    for (id, (package, version)) in selected {
374	        if crate::commands::snapshot::is_snapshot_version(version) {
375	            return Err(GraphError::ReleaseSelectionInvalid {
376	                package: id.clone(),
377	                reason: ReleaseSelectionInvalidReason::SnapshotVersion,
378	            });
379	        }
380	        let produces_tag = package
381	            .publish_to
382	            .iter()
383	            .any(|target| !matches!(target, PublishTarget::None));
384	        let fingerprint = package_fingerprint(
385	            workspace,
386	            id,
387	            package,
388	            version,
389	            produces_tag.then_some(git_remote).flatten(),
390	        )?;
391	        package_inputs.push(ReleasePackageInputV1 {
392	            package: id.clone(),
393	            fingerprint,
394	        });
395	
396	        let mut publishes = Vec::new();
397	        for target in &package.publish_to {
398	            if !target.is_implemented() {
399	                return Err(GraphError::PublishTargetNotImplemented {
400	                    package: id.clone(),
401	                    target: target.config_str(),
402	                });
403	            }
404	            if target.ecosystem() == Some(id.ecosystem()) {
405	                super::provider::registry::require_observable_registry(id.ecosystem())?;
406	                let binding = prepared_registry_binding(workspace, target, &package.id)?;
407	                let binding_id = RegistryBindingId::new(binding.key.as_str(), binding.identity.clone())?;
408	                let operation =
409	                    ReleaseOperation::registry_publish(id.clone(), version.clone(), binding_id.clone(), Vec::new())?;
410	                // A durable registry operation must have one exact endpoint
411	                // binding. The model-level operation identity currently has
412	                // only a registry key, so reject a second target that would
413	                // collapse to the same operation until the typed binding
414	                // identity is added there.
415	                if prepared.contains_key(operation.id()) {
416	                    return Err(GraphError::ReleaseSelectionInvalid {
417	                        package: id.clone(),
418	                        reason: ReleaseSelectionInvalidReason::DuplicateRegistryTarget,
419	                    });
420	                }
421	                let explicit_access = match target {
422	                    PublishTarget::Npm { access, .. } => *access,
423	                    _ => None,
424	                };
425	                let npm_tag = matches!(target, PublishTarget::Npm { .. })
426	                    .then(|| npm_dist_tag(version))
427	                    .flatten();
428	                if matches!(target, PublishTarget::Npm { .. }) {
429	                    let mut platform_ids = Vec::new();
430	                    for (name, manifest) in workspace.identity.attached_platforms(package) {
431	                        let directory = manifest.parent().unwrap_or(std::path::Path::new(""));
432	                        let platform = PlatformPackageV1::new(
433	                            ReleasePackageId::new(callisto_model::Ecosystem::Npm, name)?,
434	                            directory.to_string_lossy().replace('\\', "/"),
435	                        )?;
436	                        let platform_operation = ReleaseOperation::new(
437	                            callisto_model::ReleaseOperationId::platform_publish(
438	                                id.clone(),
439	                                version.clone(),
440	                                binding_id.clone(),
441	                                platform,
442	                            ),
443	                            Vec::new(),
444	                        )?;
445	                        prepared.insert(
446	                            platform_operation.id().clone(),
447	                            PreparedOperation::RegistryPublish(RegistryPublishOperation {
448	                                package_dir: directory.to_path_buf(),
449	                                package_name: name.to_string(),
450	                                version: version.clone(),
451	                                registry: prepared_registry_binding(workspace, target, &package.id)?,
452	                                npm_access: npm_default_access(name, explicit_access),
453	                                npm_tag: npm_tag.clone(),
454	                                by_directory: true,
455	                            }),
456	                        );
457	                        platform_ids.push(platform_operation.id().clone());
458	                        operations.insert(platform_operation.id().clone(), platform_operation);
459	                    }
460	                    platforms_by_publish.insert(operation.id().clone(), platform_ids);
461	                }
462	                prepared.insert(
463	                    operation.id().clone(),
464	                    PreparedOperation::RegistryPublish(RegistryPublishOperation {
465	                        package_dir: package_dir(package)?,
466	                        package_name: id.name().to_string(),
467	                        version: version.clone(),
468	                        registry: binding,
469	                        npm_access: matches!(target, PublishTarget::Npm { .. })
470	                            .then(|| npm_default_access(id.name(), explicit_access))
471	                            .flatten(),
472	                        npm_tag,
473	                        by_directory: false,
474	                    }),
475	                );
476	                publishes.push(operation.id().clone());
477	                operations.insert(operation.id().clone(), operation);
478	            }
479	        }
480	        publishes.sort();
481	        publishes_by_package.insert(id.clone(), publishes);
482	    }
483	    Ok(())
484	}
