604	fn add_forge_releases<R: CommandRunner, D: DependencyResolver>(
605	    workspace: &Workspace<'_, R, D>,
606	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
607	    owners: &Owners,
608	    ops: &mut Ops,
609	) -> Result<(), GraphError> {
610	    let Ops {
611	        operations,
612	        prepared,
613	        index: OpIndex {
614	            tag_by_package,
615	            forge_by_package,
616	            ..
617	        },
618	        ..
619	    } = ops;
620	
621	    for (id, (package, version)) in owned(selected, owners) {
622	        if package
623	            .publish_to
624	            .iter()
625	            .any(|target| matches!(target, PublishTarget::GitHubRelease))
626	        {
627	            let tag = tag_by_package.get(id).expect("release point has tag").clone();
628	            let operation = ReleaseOperation::forge_release(id.clone(), version.clone(), vec![tag])?;
629	            let tag = match prepared.get(operation.prerequisites().first().expect("forge release has tag")) {
630	                Some(PreparedOperation::Tag(prepared_tag)) => prepared_tag.name.clone(),
631	                _ => {
632	                    return Err(GraphError::ReleaseInvariant {
633	                        detail: format!(
634	                            "forge release `{:?}` prerequisite is not a prepared Tag operation",
635	                            operation.id()
636	                        ),
637	                    })
638	                }
639	            };
640	            prepared.insert(
641	                operation.id().clone(),
642	                PreparedOperation::ForgeRelease(ForgeReleaseOperation {
643	                    tag,
644	                    prerelease: version.is_prerelease(),
645	                    notes: release_notes(&workspace.root, package.changelog.as_deref(), version)?,
646	                }),
647	            );
648	            forge_by_package.insert(id.clone(), operation.id().clone());
649	            operations.insert(operation.id().clone(), operation);
650	        }
651	    }
652	    Ok(())
653	}
654	
655	/// The artifact slots and their upload operations, with the uploads each product package's forge publish waits on.
656	fn add_artifact_uploads<R: CommandRunner, D: DependencyResolver>(
657	    workspace: &Workspace<'_, R, D>,
658	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
659	    owners: &Owners,
660	    artifact_policy: Option<&ArtifactBuildPolicy>,
661	    ops: &mut Ops,
662	    diagnostics: &mut Vec<Diagnostic>,
663	) -> Result<Vec<ArtifactSlotId>, GraphError> {
664	    let Ops {
665	        operations,
666	        prepared,
667	        index:
668	            OpIndex {
669	                tag_by_package,
670	                forge_by_package,
671	                uploads_by_package,
672	                asset_owner_tags_by_package,
673	                ..
674	            },
675	    } = ops;
676	
677	    let mut artifact_slots = Vec::new();
678	    if let (Some(product), Some(policy)) = (&workspace.config.product_release, artifact_policy) {
679	        require_product_package_publishes_to_forge(workspace, &product.package)?;
680	        // Resolved through IdentityIndex, not `PackageId::matches`: a Bare
681	        // package id is not an ecosystem wildcard here -- a same-name
682	        // package in another ecosystem must never match the product/artifact selector.
683	        let matches_product =
684	            |package: &callisto_model::Package| workspace.identity.identifies(&product.package, &package.id);
685	        if !selected.values().any(|(package, _)| matches_product(package)) {
686	            // The product isn't in this release, so warn instead of leaving the artifact owner's asset unregistered.
687	            for artifact in &product.artifacts {
688	                if let Some((owner_id, _)) = owned(selected, owners)
689	                    .find(|(_, (pkg, _))| workspace.identity.identifies(&artifact.package, &pkg.id))
690	                {
691	                    diagnostics.push(unreleased_product_artifact_diagnostic(
692	                        &product.package,
693	                        artifact,
694	                        owner_id,
695	                    ));
696	                }
697	            }
698	        }
699	        for (id, (package, _)) in owned(selected, owners) {
700	            if !matches_product(package) {
701	                continue;
702	            }
703	            let forge = forge_by_package.get(id).ok_or_else(|| GraphError::ReleaseInvariant {
704	                detail: format!("product package `{id}` has no forge release operation"),
705	            })?;
706	            let (tag, prerelease) = match prepared.get(forge) {
707	                Some(PreparedOperation::ForgeRelease(prepared_forge)) => {
708	                    (prepared_forge.tag.clone(), prepared_forge.prerelease)
709	                }
710	                _ => {
711	                    return Err(GraphError::ReleaseInvariant {
712	                        detail: format!("product forge release `{forge:?}` is not prepared"),
713	                    })
714	                }
715	            };
716	            for artifact in &product.artifacts {
717	                // The slot names the package whose build produced the bytes, which
718	                // need not be the product -- a plugin can ship on the product's
719	                // release. Every slot still attaches to the product's one release.
720	                let (owner_id, owner_version) = owned(selected, owners)
721	                    .find(|(_, (pkg, _))| workspace.identity.identifies(&artifact.package, &pkg.id))
722	                    .map(|(candidate, (_, owner_version))| (candidate.clone(), owner_version.clone()))
723	                    .ok_or_else(|| GraphError::ReleaseArtifactOwnerNotReleased {
724	                        asset: artifact.asset_name.clone(),
725	                        package: artifact.package.to_string(),
726	                    })?;
727	                let slot = ArtifactSlotId::new(
728	                    owner_id.clone(),
729	                    owner_version.clone(),
730	                    &artifact.target,
731	                    artifact.asset_name.clone(),
732	                    policy.repository.clone(),
733	                    policy.workflow_path.clone(),
734	                    policy.workflow_commit.clone(),
735	                )
736	                .map_err(|error| GraphError::ReleaseInvariant {
737	                    detail: format!("invalid configured artifact slot: {error}"),
738	                })?;
739	                let operation = ReleaseOperation::artifact_upload(slot.clone(), vec![forge.clone()])?;
740	                prepared.insert(
741	                    operation.id().clone(),
742	                    PreparedOperation::ArtifactUpload(ArtifactUploadOperation {
743	                        slot: slot.clone(),
744	                        tag: tag.clone(),
745	                        prerelease,
746	                    }),
747	                );
748	                // Keyed by the product's id: a plugin-built asset must still gate the product's own forge-publish.
749	                uploads_by_package
750	                    .entry(id.clone())
751	                    .or_default()
752	                    .push(operation.id().clone());
753	                if owner_id != *id
754	                    && let Some(owner_tag) = tag_by_package.get(&owner_id)
755	                {
756	                    asset_owner_tags_by_package
757	                        .entry(id.clone())
758	                        .or_default()
759	                        .insert(owner_tag.clone());
760	                }
761	                operations.insert(operation.id().clone(), operation);
762	                artifact_slots.push(slot);
763	            }
764	        }
765	    }
766	    Ok(artifact_slots)
767	}
768	
769	fn add_forge_publishes(
770	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
771	    owners: &Owners,
772	    ops: &mut Ops,
773	) -> Result<(), GraphError> {
774	    let Ops {
775	        operations,
776	        prepared,
777	        index:
778	            OpIndex {
779	                forge_by_package,
780	                uploads_by_package,
781	                asset_owner_tags_by_package,
782	                ..
783	            },
784	    } = ops;
785	
786	    // Publishing is the last forge step: a GitHub Release is only complete
787	    // once every asset it carries has been uploaded to it as a draft.
788	    for (id, (_, version)) in owned(selected, owners) {
789	        let Some(forge) = forge_by_package.get(id) else {
790	            continue;
791	        };
792	        let mut prerequisites = vec![forge.clone()];
793	        prerequisites.extend(uploads_by_package.get(id).into_iter().flatten().cloned());
794	        prerequisites.extend(asset_owner_tags_by_package.get(id).into_iter().flatten().cloned());
795	        let operation = ReleaseOperation::forge_publish(id.clone(), version.clone(), prerequisites)?;
796	        let tag = match prepared.get(forge) {
797	            Some(PreparedOperation::ForgeRelease(prepared_forge)) => prepared_forge.tag.clone(),
798	            _ => {
799	                return Err(GraphError::ReleaseInvariant {
800	                    detail: format!("forge publish `{:?}` has no prepared draft release", operation.id()),
801	                })
802	            }
803	        };
804	        prepared.insert(
805	            operation.id().clone(),
806	            PreparedOperation::ForgePublish(ForgePublishOperation {
807	                tag,
808	                prerelease: version.is_prerelease(),
809	            }),
810	        );
811	        operations.insert(operation.id().clone(), operation);
812	    }
813	    Ok(())
814	}
815	
816	/// Every unreleased, publishable workspace package a selected package reaches
817	/// through a runtime, optional, or peer edge must be selected with it, or the
818	/// selected package would publish pointing at a version that does not exist.
819	/// Standalone npm platform packages are one case of this.
820	fn require_dependencies_selected<R: CommandRunner, D: DependencyResolver>(
821	    workspace: &Workspace<'_, R, D>,
822	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
823	    package_ids: &BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
824	) -> Result<(), GraphError> {
825	    let mut base_versions = None;
826	    for (package, _) in selected.values() {
827	        for edge in workspace.graph.dependencies_of(&package.id) {
828	            if !matches!(edge.kind, DepKind::Runtime | DepKind::Optional | DepKind::Peer)
829	                || package_ids.contains_key(&edge.to)
830	            {
831	                continue;
832	            }
833	            let Some(dependency) = workspace
834	                .graph
835	                .packages()
836	                .find(|candidate| candidate.id == edge.to && has_dispatchable_target(candidate))
837	            else {
838	                continue;
839	            };
840	            if base_versions.is_none() {
841	                base_versions = Some(workspace.base_versions()?);
842	            }
843	            let tags = workspace.tags()?;
844	            let released = base_versions
845	                .as_ref()
846	                .and_then(|versions| versions.get(&dependency.id))
847	                .is_some_and(|current| version_is_tagged(tags, &dependency.id, current));
848	            if !released {
849	                let id = crate::commands::release_decision::release_package_ids(&workspace.identity, dependency)?
850	                    .into_iter()
851	                    .next()
852	                    .ok_or_else(|| GraphError::ReleaseInvariant {
853	                        detail: format!("package `{}` has no release identity", dependency.id.display_name()),
854	                    })?;
855	                return Err(GraphError::ReleaseSelectionInvalid {
856	                    package: id,
857	                    reason: ReleaseSelectionInvalidReason::DependencyNotSelected,
858	                });
859	            }
860	        }
861	    }
862	    Ok(())
863	}
864	
865	/// A configured product package must exist and publish to github-release; otherwise
866	/// derivation would silently yield zero artifact slots.
867	fn require_product_package_publishes_to_forge<R: CommandRunner, D: DependencyResolver>(
868	    workspace: &Workspace<'_, R, D>,
869	    product: &callisto_model::PackageId,
870	) -> Result<(), GraphError> {
871	    let mut found = false;
872	    for package in workspace.graph.packages() {
873	        if !workspace.identity.identifies(product, &package.id) {
874	            continue;
875	        }
876	        found = true;
877	        if package
878	            .publish_to
879	            .iter()
880	            .any(|target| matches!(target, PublishTarget::GitHubRelease))
881	        {
882	            return Ok(());
883	        }
884	    }
885	    let detail = if found {
886	        format!("product-package `{product}` does not publish to github-release")
887	    } else {
888	        format!("product-package `{product}` is not a package in this workspace")
889	    };
890	    Err(crate::error::ConfigError::InvalidProductRelease { detail }.into())
891	}
892	
893	/// Warns that `owner`'s asset has no release to attach to, since its product isn't selected for release.
894	fn unreleased_product_artifact_diagnostic(
895	    product: &callisto_model::PackageId,
896	    artifact: &crate::config::resolve::ProductArtifactConfig,
897	    owner: &ReleasePackageId,
898	) -> Diagnostic {
899	    Diagnostic {
900	        code: DiagnosticCode::ProductArtifactOwnerWithoutProduct,
901	        severity: DiagnosticSeverity::Warning,
902	        message: format!(
903	            "{owner} is selected but product `{product}` is not; its `{}` asset will not be uploaded",
904	            artifact.asset_name
905	        ),
906	        package: callisto_model::PackageId::parse(&owner.to_string()).ok(),
907	        path: None,
908	        escalated_by: None,
909	        governed_by: None,
910	    }
911	}
912	
913	fn package_fingerprint<R: CommandRunner, D: DependencyResolver>(
914	    workspace: &Workspace<'_, R, D>,
915	    id: &ReleasePackageId,
916	    package: &callisto_model::Package,
917	    version: &Version,
918	    git_remote: Option<&PreparedGitRemote>,
919	) -> Result<SemanticInputDigest, GraphError> {
920	    let mut transcript = CanonicalTranscript::semantic_input_v1();
921	    transcript.push_str("package.id", &id.to_string());
922	    transcript.push_str("package.version", version.render());
923	    for manifest in &package.manifests {
924	        let path = workspace.root.join(&manifest.path);
925	        let bytes = std::fs::read(&path).map_err(|error| GraphError::ReleaseInputRead {
926	            path: manifest.path.clone(),
927	            message: error.to_string(),
928	        })?;
929	        transcript.push_str("manifest.path", &manifest.path.display().to_string());
930	        transcript.push_str("manifest.bytes", digest_bytes("manifest", &bytes).as_str());
931	        transcript.push_str("manifest.role", &manifest_role_text(&manifest.role));
932	        transcript.push_str("manifest.format", manifest.format.ecosystem().prefix());
933	    }
934	    transcript.push_str("package.trigger", release_trigger_text(package.release_trigger));
935	    transcript.push_str(
936	        "package.tag",
937	        &package
938	            .tag_template
939	            .as_ref()
940	            .map_or_else(|| "default".to_string(), |tag| tag.as_str()),
941	    );
942	    let npm_name = workspace
943	        .identity
944	        .native_name(&package.id, callisto_model::Ecosystem::Npm)
945	        .unwrap_or(package.id.name());
946	    for target in &package.publish_to {
947	        transcript.push_str(
948	            "package.target",
949	            target_fingerprint(workspace, &package.id, npm_name, target)?.as_str(),
950	        );
951	    }
952	    if let Some(remote) = git_remote {
953	        transcript.push_str("package.gitRemote", remote.identity.as_str());
954	    }
955	    Ok(SemanticInputDigest::from_transcript(&transcript))
956	}
