958	pub(crate) fn package_dir(package: &callisto_model::Package) -> Result<std::path::PathBuf, GraphError> {
959	    package
960	        .key()
961	        .map(|key| key.as_path().to_path_buf())
962	        .ok_or_else(|| GraphError::ReleaseInvariant {
963	            detail: format!("selected release package `{}` has no canonical manifest", package.id),
964	        })
965	}
966	
967	fn manifest_role_text(role: &callisto_model::ManifestRole) -> String {
968	    match role {
969	        callisto_model::ManifestRole::Canonical => "canonical".to_string(),
970	        callisto_model::ManifestRole::Lockfile => "lockfile".to_string(),
971	        callisto_model::ManifestRole::Platform { platform, arch, abi } => {
972	            format!("platform:{platform}:{arch}:{}", abi.as_deref().unwrap_or(""))
973	        }
974	    }
975	}
