977	fn release_trigger_text(trigger: callisto_model::ReleaseTrigger) -> &'static str {
978	    match trigger {
979	        callisto_model::ReleaseTrigger::Changeset => "changeset",
980	        callisto_model::ReleaseTrigger::Auto => "auto",
981	    }
