984	pub(crate) fn canonical_operation_order(
985	    mut operations: BTreeMap<ReleaseOperationId, ReleaseOperation>,
986	) -> Result<Vec<ReleaseOperation>, GraphError> {
987	    let order = callisto_model::canonical_operation_order(
988	        operations
989	            .iter()
990	            .map(|(id, operation)| (id.clone(), operation.prerequisites().to_vec())),
991	    )
992	    .map_err(|source| GraphError::ReleaseInvariant {
993	        detail: format!("the release operations do not form a valid DAG: {source}"),
994	    })?;
995	    order
996	        .iter()
997	        .map(|id| {
998	            operations.remove(id).ok_or_else(|| GraphError::ReleaseInvariant {
999	                detail: format!("the canonical order names an operation that was not planned: {id}"),
1000	            })

