244	/// branch as `target_commitish`, so that field proves nothing about the
245	/// released commit. The tag operation is a DAG prerequisite of the forge
246	/// release, so the tag already binds this release's name to its commit.
247	fn observed_forge_release(
248	    context: &ProviderContext<'_>,
249	    tag: &TagName,
250	    prerelease: bool,
251	    repository: &str,
252	    draft_policy: Draft,
253	) -> Result<ProviderObservationV1, GraphError> {
