258	                cause: ProviderIndeterminateCause::ProviderStatus { status },
259	            })
260	        }
261	        GitHubReleaseLookup::CommandFailed => {
262	            return Ok(ProviderObservationV1::Indeterminate {
263	                cause: ProviderIndeterminateCause::CommandFailed,
264	            })
265	        }
266	        GitHubReleaseLookup::Found(value) => value,
267	    };
