269	        return Ok(ProviderObservationV1::Conflict {
270	            reason: ProviderConflictReason::ForgeReleaseDiffers,
271	        });
272	    }
273	    if value
274	        .get("prerelease")
275	        .and_then(serde_json::Value::as_bool)
