285	        return Ok(ProviderObservationV1::Absent);
286	    }
287	    Ok(ProviderObservationV1::Exact {
288	        evidence: ProviderEvidenceV1::ForgeRelease {
289	            tag_name: tag.clone(),
290	            draft,
291	        },
292	    })
293	}
