230	    /// Regression: a timed-out `gh api` call must retry, not hand `CommandError::TimedOut` straight to `?`.
231	    #[test]
232	    fn a_timed_out_gh_api_call_retries_and_settles() {
233	        struct FlakyGh(
234	            std::sync::Mutex<std::collections::VecDeque<Result<CommandOutput, callisto_model::CommandError>>>,
235	        );
236	        impl CommandRunner for FlakyGh {
237	            fn run(
238	                &self,
239	                program: &str,
240	                _args: &[&str],
241	                _cwd: &Path,
242	            ) -> Result<CommandOutput, callisto_model::CommandError> {
243	                assert_eq!(program, "gh");
244	                self.0.lock().unwrap().pop_front().expect("script exhausted")
245	            }
246	        }
247	        let runner = FlakyGh(std::sync::Mutex::new(
248	            vec![
249	                Err(callisto_model::CommandError::TimedOut {
250	                    program: "gh".to_owned(),
251	                    seconds: 60,
252	                }),
253	                Ok(CommandOutput {
254	                    exit_code: Some(1),
255	                    stdout: "HTTP/2 404\r\ncontent-type: application/json\r\n\r\n{\"message\":\"Not Found\"}"
256	                        .to_owned(),
257	                    stderr: "gh: Not Found (HTTP 404)".to_owned(),
258	                }),
259	            ]
260	            .into(),
261	        ));
262	        let sleeper = super::super::provider::policy::tests::RecordingSleeper::new();
263	        let root = std::env::temp_dir();
264	        let result = retry_observation(&sleeper, || {
265	            github_api_get_once(&root, &runner, "repos/o/r/releases/tags/v1")
266	        });
267	        assert!(matches!(result, Ok(GitHubReleaseLookup::Absent)));
268	        assert_eq!(sleeper.waits(), vec![std::time::Duration::from_secs(2)]);
269	    }
