13	/// A closed, credential-safe reason why an operation was blocked.
14	///
15	/// This deliberately carries no endpoint, command output, or arbitrary error
16	/// text: durable execution records can safely outlive the process that made
17	/// the observation.
18	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
19	#[serde(rename_all = "camelCase")]
20	#[non_exhaustive]
21	pub enum OperationBlockReason {
22	    /// An existing remote or VCS object does not exactly match the intent.
23	    ConflictingExistingOperation,
24	    /// A completed attempt could not be conclusively observed after restart.
25	    IndeterminateAttempt,
26	    /// Fresh validation no longer agrees with the approved intent.
27	    StaleValidation,
28	    /// An exact prerequisite has not reached a successful terminal outcome.
29	    UnmetPrerequisite,
30	}
