91	impl ReleaseRunEnvelopeV1 {
92	    /// 3 removes the release `profile`.
93	    pub const SCHEMA_VERSION: u8 = 3;
94	
95	    /// The only constructor. Source revision, and intent digest are
96	    /// read out of `intent`; only the coordinator revision and the verified
97	    /// manifest digest come from the caller, and both are cross-checked
98	    /// against the intent here, before any effect.
99	    pub fn new(
100	        orchestration_revision: CommitSha,
101	        intent: &ReleaseIntentV1,
102	        artifact_manifest_digest: Option<ArtifactDigest>,
103	    ) -> Result<Self, ReleaseRunEnvelopeError> {
104	        let release_source_revision = match &intent.snapshot.source {
105	            SourceIdentity::GitCommit { sha } => sha.clone(),
106	            SourceIdentity::HermeticContent { .. } => return Err(ReleaseRunEnvelopeError::NonGitReleaseSource),
107	        };
108	        let envelope = Self {
109	            schema_version: Self::SCHEMA_VERSION,
110	            orchestration_revision,
111	            release_source_revision,
112	            intent_digest: intent.digest.clone(),
113	            artifact_manifest_digest,
114	        };
115	        envelope.validate_for_intent(intent)?;
116	        Ok(envelope)
117	    }
118	
119	    pub fn orchestration_revision(&self) -> &CommitSha {
120	        &self.orchestration_revision
121	    }
122	
123	    pub fn release_source_revision(&self) -> &CommitSha {
124	        &self.release_source_revision
125	    }
126	
127	    pub fn intent_digest(&self) -> &IntentDigest {
128	        &self.intent_digest
129	    }
130	
131	    pub fn artifact_manifest_digest(&self) -> Option<&ArtifactDigest> {
132	        self.artifact_manifest_digest.as_ref()
133	    }
134	
135	    /// Cross-field validity against the exact intent this run releases.
136	    pub fn validate_for_intent(&self, intent: &ReleaseIntentV1) -> Result<(), ReleaseRunEnvelopeError> {
137	        if self.schema_version != Self::SCHEMA_VERSION {
138	            return Err(ReleaseRunEnvelopeError::UnsupportedSchema {
139	                found: self.schema_version,
140	            });
141	        }
142	        if self.intent_digest != intent.digest {
143	            return Err(ReleaseRunEnvelopeError::MismatchedIntent);
144	        }
145	        let sealable = !intent.artifact_slots.is_empty() || !super::python_publishes(intent).is_empty();
146	        match (intent.artifact_slots.is_empty(), &self.artifact_manifest_digest) {
147	            (false, None) => return Err(ReleaseRunEnvelopeError::MissingArtifactManifest),
148	            (true, Some(_)) if !sealable => return Err(ReleaseRunEnvelopeError::UnexpectedArtifactManifest),
149	            _ => {}
150	        }
151	        // The coordinator that built and attested the binaries is the same
152	        // revision the slots' attestation policy pins; a receipt must not be
153	        // able to name a coordinator that did not produce these artifacts.
154	        for slot in &intent.artifact_slots {
155	            if slot.attestation_policy.workflow_commit != self.orchestration_revision {
156	                return Err(ReleaseRunEnvelopeError::MismatchedOrchestrationRevision);
157	            }
158	        }
159	        match &intent.snapshot.source {
160	            SourceIdentity::GitCommit { sha } if sha == &self.release_source_revision => Ok(()),
161	            SourceIdentity::GitCommit { .. } => Err(ReleaseRunEnvelopeError::MismatchedReleaseSource),
162	            SourceIdentity::HermeticContent { .. } => Err(ReleaseRunEnvelopeError::NonGitReleaseSource),
163	        }
164	    }
165	}
