215	impl ReleaseExecutionStateV1 {
216	    /// Starts execution for exactly the roster authorized by `intent`, under
217	    /// the run envelope that was validated before any effect. There is no way
218	    /// to create a state without an envelope.
219	    pub fn new(intent: &ReleaseIntentV1, envelope: ReleaseRunEnvelopeV1) -> Result<Self, ReleaseStateError> {
220	        envelope
221	            .validate_for_intent(intent)
222	            .map_err(ReleaseStateError::InvalidEnvelope)?;
223	        Ok(Self {
224	            intent_digest: intent.digest.clone(),
225	            envelope,
226	            operations: intent
227	                .operations
228	                .iter()
229	                .map(|operation| (operation.id.clone(), OperationState::Pending))
230	                .collect(),
231	            evidence: BTreeMap::new(),
232	        })
233	    }
