235	    pub fn intent_digest(&self) -> &IntentDigest {
236	        &self.intent_digest
237	    }
238	
239	    /// The run this state belongs to: the single authority for coordinator
240	    /// revision, release source, and manifest digest.
241	    pub fn envelope(&self) -> &ReleaseRunEnvelopeV1 {
242	        &self.envelope
243	    }
244	
245	    /// Validates that this state belongs to this exact intent and operation roster.
246	    pub fn validate_for_intent(&self, intent: &ReleaseIntentV1) -> Result<(), ReleaseStateError> {
247	        if self.intent_digest != intent.digest {
248	            return Err(ReleaseStateError::MismatchedIntent);
249	        }
250	        self.envelope
251	            .validate_for_intent(intent)
252	            .map_err(ReleaseStateError::InvalidEnvelope)?;
253	        let expected: BTreeSet<_> = intent.operations.iter().map(|operation| operation.id.clone()).collect();
254	        let actual: BTreeSet<_> = self.operations.keys().cloned().collect();
255	        if actual != expected {
256	            return Err(ReleaseStateError::MismatchedOperationRoster);
257	        }
258	        Ok(())
259	    }
260	
261	    /// Returns the state for an exact operation identity.
262	    pub fn operation_state(&self, id: &ReleaseOperationId) -> Option<OperationState> {
263	        self.operations.get(id).copied()
264	    }
265	
266	    /// The exact evidence recorded when `id` reached a successful state.
267	    pub fn operation_evidence(&self, id: &ReleaseOperationId) -> Option<&ProviderEvidenceV1> {
268	        self.evidence.get(id)
269	    }
270	
271	    /// The only way an operation's state ever changes.
272	    pub fn apply(
273	        &mut self,
274	        id: &ReleaseOperationId,
275	        event: &OperationEvent,
276	    ) -> Result<OperationState, ReleaseStateError> {
277	        let state = self
278	            .operations
279	            .get_mut(id)
280	            .ok_or_else(|| ReleaseStateError::UnknownOperation {
281	                id: Box::new(id.clone()),
282	            })?;
283	        let next = crate::release_transition::transition(*state, event).map_err(|source| {
284	            ReleaseStateError::InvalidTransition {
285	                id: Box::new(id.clone()),
286	                source,
287	            }
288	        })?;
289	        let proof = if next.is_success() {
290	            let proof = event
291	                .exact_evidence()
292	                .ok_or_else(|| ReleaseStateError::MissingEvidence {
293	                    id: Box::new(id.clone()),
294	                })?;
295	            check_evidence_role(id, proof.evidence())?;
296	            Some(proof.evidence().clone())
297	        } else {
298	            None
299	        };
300	        *state = next;
301	        if let Some(proof) = proof {
302	            self.evidence.insert(id.clone(), proof);
303	        }
304	        Ok(next)
305	    }
306	}
