418	impl ReleaseReceiptV1 {
419	    pub const SCHEMA_VERSION: u8 = 2;
420	
421	    /// Constructs a receipt from a terminal state alone: every operation must
422	    /// be successful, and its recorded evidence becomes its observation.
423	    ///
424	    /// The run envelope comes from the state, which was created and validated
425	    /// before the first effect; nothing is assembled after the fact here.
426	    pub fn from_state(intent: &ReleaseIntentV1, state: &ReleaseExecutionStateV1) -> Result<Self, ReleaseReceiptError> {
427	        state
428	            .validate_for_intent(intent)
429	            .map_err(ReleaseReceiptError::InvalidState)?;
430	        let mut outcomes = BTreeMap::new();
431	        let mut observations = BTreeMap::new();
432	        for (id, operation_state) in &state.operations {
433	            let outcome = match operation_state {
434	                OperationState::Published => OperationOutcome::Published,
435	                OperationState::AlreadySatisfied => OperationOutcome::AlreadySatisfied,
436	                OperationState::Failed | OperationState::Blocked { .. } => {
437	                    return Err(ReleaseReceiptError::NonSuccessfulOperation {
438	                        id: Box::new(id.clone()),
439	                    });
440	                }
441	                OperationState::Pending | OperationState::Attempting => {
442	                    return Err(ReleaseReceiptError::NonTerminalOperation {
443	                        id: Box::new(id.clone()),
444	                    });
445	                }
446	            };
447	            let evidence = state.operation_evidence(id).cloned().ok_or_else(|| {
448	                ReleaseReceiptError::InvalidState(ReleaseStateError::MissingEvidence {
449	                    id: Box::new(id.clone()),
450	                })
451	            })?;
452	            outcomes.insert(id.clone(), outcome);
453	            observations.insert(id.clone(), ProviderObservationV1::Exact { evidence });
454	        }
455	        Ok(Self {
456	            schema_version: Self::SCHEMA_VERSION,
457	            intent_digest: state.intent_digest.clone(),
458	            envelope: state.envelope().clone(),
459	            outcomes,
460	            observations,
461	        })
462	    }
463	
464	    /// The exact provider observation this receipt records for `id`.
465	    pub fn observation(&self, id: &ReleaseOperationId) -> Option<&ProviderObservationV1> {
466	        self.observations.get(id)
467	    }
468	
469	    pub fn intent_digest(&self) -> &IntentDigest {
470	        &self.intent_digest
471	    }
472	
473	    /// Validates exact intent and operation-roster binding before reconciliation.
474	    pub fn validate_for_intent(&self, intent: &ReleaseIntentV1) -> Result<(), ReleaseReceiptError> {
475	        if self.schema_version != Self::SCHEMA_VERSION {
476	            return Err(ReleaseReceiptError::UnsupportedSchema {
477	                found: self.schema_version,
478	            });
479	        }
480	        if self.intent_digest != intent.digest {
481	            return Err(ReleaseReceiptError::MismatchedIntent);
482	        }
483	        self.envelope
484	            .validate_for_intent(intent)
485	            .map_err(ReleaseReceiptError::InvalidEnvelope)?;
486	        let expected: BTreeSet<_> = intent.operations.iter().map(|operation| operation.id.clone()).collect();
487	        let actual: BTreeSet<_> = self.outcomes.keys().cloned().collect();
488	        if actual != expected {
489	            return Err(ReleaseReceiptError::MismatchedOperationRoster);
490	        }
491	        let observed: BTreeSet<_> = self.observations.keys().cloned().collect();
492	        if observed != expected {
493	            return Err(ReleaseReceiptError::MismatchedObservationRoster);
494	        }
495	        if self
496	            .observations
497	            .values()
498	            .any(|observation| !observation.is_terminal_success())
499	        {
500	            return Err(ReleaseReceiptError::NonExactReceiptObservation);
501	        }
502	        Ok(())
503	    }
504	
505	    fn from_wire(wire: ReleaseReceiptV1Wire) -> Result<Self, ReleaseReceiptError> {
506	        if wire.schema_version != Self::SCHEMA_VERSION {
507	            return Err(ReleaseReceiptError::UnsupportedSchema {
508	                found: wire.schema_version,
509	            });
510	        }
511	        let mut outcomes = BTreeMap::new();
512	        for entry in wire.outcomes {
513	            if !matches!(
514	                entry.outcome,
515	                OperationOutcome::Published | OperationOutcome::AlreadySatisfied
516	            ) {
517	                return Err(ReleaseReceiptError::NonSuccessfulOperation {
518	                    id: Box::new(entry.operation),
519	                });
520	            }
521	            if outcomes.insert(entry.operation.clone(), entry.outcome).is_some() {
522	                return Err(ReleaseReceiptError::DuplicateOperation {
523	                    id: Box::new(entry.operation),
524	                });
525	            }
526	        }
527	        let mut observations = BTreeMap::new();
528	        for entry in wire.observations {
529	            let (operation, observation) = entry.into_parts();
530	            if !observation.is_terminal_success() {
531	                return Err(ReleaseReceiptError::NonExactObservation {
532	                    id: Box::new(operation),
533	                    observation: Box::new(observation),
534	                });
535	            }
536	            if observations.insert(operation.clone(), observation).is_some() {
537	                return Err(ReleaseReceiptError::DuplicateObservation {
538	                    id: Box::new(operation),
539	                });
540	            }
541	        }
542	        Ok(Self {
543	            schema_version: wire.schema_version,
544	            intent_digest: wire.intent_digest,
545	            envelope: wire.envelope,
546	            outcomes,
547	            observations,
548	        })
549	    }
550	}
