556	    UnsupportedSchema { found: u8 },
557	    #[error("release receipt is bound to a different intent")]
558	    MismatchedIntent,
559	    #[error("release receipt operation roster differs from the bound intent")]
560	    MismatchedOperationRoster,
561	    #[error("release receipt contains duplicate operation `{id:?}")]
562	    DuplicateOperation { id: Box<ReleaseOperationId> },
563	    #[error("release receipt cannot be derived from invalid state: {0}")]
564	    InvalidState(ReleaseStateError),
565	    #[error("release receipt envelope is not bound to the intent: {0}")]
566	    InvalidEnvelope(ReleaseRunEnvelopeError),
