421	    /// Constructs a receipt from a terminal state alone: every operation must
422	    /// be successful, and its recorded evidence becomes its observation.
423	    ///
424	    /// The run envelope comes from the state, which was created and validated
425	    /// before the first effect; nothing is assembled after the fact here.
426	    pub fn from_state(intent: &ReleaseIntentV1, state: &ReleaseExecutionStateV1) -> Result<Self, ReleaseReceiptError> {
427	        state
428	            .validate_for_intent(intent)
429	            .map_err(ReleaseReceiptError::InvalidState)?;
430	        let mut outcomes = BTreeMap::new();
431	        let mut observations = BTreeMap::new();
432	        for (id, operation_state) in &state.operations {
433	            let outcome = match operation_state {
434	                OperationState::Published => OperationOutcome::Published,
435	                OperationState::AlreadySatisfied => OperationOutcome::AlreadySatisfied,
436	                OperationState::Failed | OperationState::Blocked { .. } => {
437	                    return Err(ReleaseReceiptError::NonSuccessfulOperation {
438	                        id: Box::new(id.clone()),
439	                    });
440	                }
441	                OperationState::Pending | OperationState::Attempting => {
442	                    return Err(ReleaseReceiptError::NonTerminalOperation {
443	                        id: Box::new(id.clone()),
444	                    });
445	                }
446	            };
447	            let evidence = state.operation_evidence(id).cloned().ok_or_else(|| {
448	                ReleaseReceiptError::InvalidState(ReleaseStateError::MissingEvidence {
449	                    id: Box::new(id.clone()),
450	                })
451	            })?;
452	            outcomes.insert(id.clone(), outcome);
453	            observations.insert(id.clone(), ProviderObservationV1::Exact { evidence });
454	        }
455	        Ok(Self {
456	            schema_version: Self::SCHEMA_VERSION,
457	            intent_digest: state.intent_digest.clone(),
458	            envelope: state.envelope().clone(),
459	            outcomes,
460	            observations,
461	        })
462	    }
