11	/// Something that happened to one operation, carrying the proof that
12	/// authorizes it.
13	#[derive(Debug)]
14	pub enum OperationEvent {
15	    /// About to issue the effect; the provider was observed absent.
16	    Attempt {
17	        proof: AbsentProof,
18	    },
19	    /// Pre-effect observation found the provider already holds exactly this result.
20	    ObservedExactBeforeEffect {
21	        evidence: ExactEvidence,
22	    },
23	    /// The effect was issued and then observed exact.
24	    Confirmed {
25	        evidence: ExactEvidence,
26	    },
27	    /// The effect failed and the provider is proven to hold nothing.
28	    EffectFailedAndAbsent {
29	        proof: AbsentProof,
30	    },
31	    Blocked {
32	        reason: OperationBlockReason,
33	    },
34	}
35	
36	/// The discriminant of an [`OperationEvent`], for error reporting and for
37	/// enumerating the table without minting proof tokens.
38	#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
39	pub enum OperationEventKind {
40	    Attempt,
41	    ObservedExactBeforeEffect,
42	    Confirmed,
43	    EffectFailedAndAbsent,
44	    Blocked,
45	}
46	
47	impl OperationEvent {
48	    /// The exact evidence this event carries, if it is a success event.
49	    pub fn exact_evidence(&self) -> Option<&ExactEvidence> {
50	        match self {
51	            Self::ObservedExactBeforeEffect { evidence } | Self::Confirmed { evidence } => Some(evidence),
52	            Self::Attempt { .. } | Self::EffectFailedAndAbsent { .. } | Self::Blocked { .. } => None,
53	        }
54	    }
55	
56	    pub fn kind(&self) -> OperationEventKind {
57	        match self {
58	            Self::Attempt { .. } => OperationEventKind::Attempt,
59	            Self::ObservedExactBeforeEffect { .. } => OperationEventKind::ObservedExactBeforeEffect,
60	            Self::Confirmed { .. } => OperationEventKind::Confirmed,
61	            Self::EffectFailedAndAbsent { .. } => OperationEventKind::EffectFailedAndAbsent,
62	            Self::Blocked { .. } => OperationEventKind::Blocked,
63	        }
64	    }
65	}
66	
67	#[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error)]
68	#[error("release operation cannot transition from {from:?} on {event:?}")]
69	pub struct InvalidTransition {
70	    pub from: OperationState,
71	    pub event: OperationEventKind,
72	}
73	
74	/// The whole legal edge set. Anything absent from this match is unreachable.
75	pub fn transition(current: OperationState, event: &OperationEvent) -> Result<OperationState, InvalidTransition> {
76	    let next = match (current, event.kind()) {
77	        (OperationState::Pending, OperationEventKind::Attempt) => Some(OperationState::Attempting),
78	        (OperationState::Pending, OperationEventKind::ObservedExactBeforeEffect) => {
79	            Some(OperationState::AlreadySatisfied)
80	        }
81	        (OperationState::Attempting, OperationEventKind::Confirmed) => Some(OperationState::Published),
82	        (OperationState::Attempting, OperationEventKind::EffectFailedAndAbsent) => Some(OperationState::Failed),
83	        (OperationState::Pending | OperationState::Attempting, OperationEventKind::Blocked) => {
84	            let OperationEvent::Blocked { reason } = event else {
85	                unreachable!("event kind Blocked is produced only by OperationEvent::Blocked")
86	            };
87	            Some(OperationState::Blocked { reason: *reason })
88	        }
89	        _ => None,
90	    };
91	    next.ok_or(InvalidTransition {
92	        from: current,
93	        event: event.kind(),
94	    })
95	}
