1	//! The file set of one Python release: what a build produced, what the index holds, and what is missing.
2	
3	use std::collections::HashMap;
4	use std::path::{Path, PathBuf};
5	use std::sync::{Arc, Mutex};
6	
7	use callisto_model::{is_pypi_sdist, is_pypi_wheel, pypi_dist_belongs_to, CommandError, Version};
8	
9	use crate::error::GraphError;
10	
11	/// One file entry of a PEP 691 JSON simple-index response: only the fields the release path reads.
12	#[derive(serde::Deserialize)]
13	pub(super) struct PypiSimpleFile {
14	    pub(super) filename: String,
15	    /// `false` when not yanked, or a (possibly empty) reason string when it is.
16	    #[serde(default)]
17	    pub(super) yanked: Option<serde_json::Value>,
18	    /// Digest by algorithm; an index that serves none leaves this empty.
19	    #[serde(default)]
20	    pub(super) hashes: HashMap<String, String>,
21	}
22	
23	#[derive(serde::Deserialize)]
24	pub(super) struct PypiSimpleIndex {
25	    pub(super) files: Vec<PypiSimpleFile>,
26	}
27	
28	impl PypiSimpleFile {
29	    pub(super) fn is_yanked(&self) -> bool {
30	        !matches!(self.yanked, None | Some(serde_json::Value::Bool(false)))
31	    }
32	
33	    fn sha256(&self) -> Option<&str> {
34	        self.hashes.get("sha256").map(String::as_str)
35	    }
36	}
37	
38	/// One distribution file of a release: built by this run, or sealed by a build job.
39	#[derive(Debug)]
40	pub(super) struct BuiltFile {
41	    pub(super) filename: String,
42	    pub(super) path: PathBuf,
43	    pub(super) sha256: String,
44	}
45	
46	/// The files of one release. A built set owns the temporary directory holding them; a sealed set points into the
47	/// verified artifact directory and compares every digest strictly.
48	#[derive(Debug)]
49	pub(super) struct BuiltSet {
50	    _dir: Option<tempfile::TempDir>,
51	    pub(super) files: Vec<BuiltFile>,
52	    sealed: bool,
53	    /// Files this run uploaded, whose index entry must then carry the same bytes.
54	    uploaded: Mutex<Vec<String>>,
55	}
56	
57	fn io_error(error: std::io::Error) -> GraphError {
58	    GraphError::Command(CommandError::Io {
59	        program: "python -m build".to_string(),
60	        message: error.to_string(),
61	    })
62	}
63	
64	/// Hex SHA-256 of `path`, streamed so a large wheel is never held in memory.
65	fn file_sha256(path: &Path) -> Result<String, GraphError> {
66	    let file = std::fs::File::open(path).map_err(io_error)?;
67	    let (digest, _) = callisto_model::ArtifactDigest::from_reader(file).map_err(io_error)?;
68	    Ok(digest.as_str().to_owned())
69	}
70	
71	/// Every wheel and sdist of `package_name` at `version` directly in `dir`, with its digest, by filename.
72	fn inventory(dir: &Path, package_name: &str, version: &Version) -> Result<Vec<BuiltFile>, GraphError> {
73	    let mut files = Vec::new();
74	    for entry in std::fs::read_dir(dir).map_err(io_error)? {
75	        let path = entry.map_err(io_error)?.path();
76	        let Some(filename) = path.file_name().and_then(|name| name.to_str()).map(str::to_owned) else {
77	            continue;
78	        };
79	        if !pypi_dist_belongs_to(&filename, package_name, version) {
80	            continue;
81	        }
82	        let sha256 = file_sha256(&path)?;
83	        files.push(BuiltFile { filename, path, sha256 });
84	    }
85	    files.sort_by(|left, right| left.filename.cmp(&right.filename));
86	    for (present, missing) in [
87	        (files.iter().any(|file| is_pypi_wheel(&file.filename)), "wheel"),
88	        (files.iter().any(|file| is_pypi_sdist(&file.filename)), "sdist"),
89	    ] {
90	        if !present {
91	            return Err(GraphError::PypiBuildOutputIncomplete {
92	                package: package_name.to_string(),
93	                version: version.clone(),
94	                missing,
95	            });
96	        }
97	    }
98	    Ok(files)
99	}
100	
101	impl BuiltSet {
102	    /// Inventories `dir`: every wheel and sdist of `package_name` at `version`, with its digest.
103	    pub(super) fn from_dir(dir: tempfile::TempDir, package_name: &str, version: &Version) -> Result<Self, GraphError> {
104	        let files = inventory(dir.path(), package_name, version)?;
105	        Ok(Self {
106	            _dir: Some(dir),
107	            files,
108	            sealed: false,
109	            uploaded: Mutex::new(Vec::new()),
110	        })
111	    }
112	
113	    /// The files a build job sealed, already checked byte for byte against the manifest.
114	    pub(super) fn sealed(files: Vec<BuiltFile>, package_name: &str, version: &Version) -> Result<Self, GraphError> {
115	        if let Some(stray) = files
116	            .iter()
117	            .find(|file| !pypi_dist_belongs_to(&file.filename, package_name, version))
118	        {
119	            return Err(GraphError::ReleaseInvariant {
120	                detail: format!(
121	                    "sealed file `{}` is not a distribution of {package_name} {}",
122	                    stray.filename,
123	                    version.render()
124	                ),
125	            });
126	        }
127	        Ok(Self {
128	            _dir: None,
129	            files,
130	            sealed: true,
131	            uploaded: Mutex::new(Vec::new()),
132	        })
133	    }
134	
135	    /// Re-hashes the files about to be uploaded: a sealed file changed after verification must not reach the index.
136	    pub(super) fn recheck(&self, files: &[&BuiltFile]) -> Result<(), GraphError> {
137	        if !self.sealed {
138	            return Ok(());
139	        }
140	        for file in files {
141	            let metadata = std::fs::symlink_metadata(&file.path).map_err(io_error)?;
142	            if !metadata.is_file() || file_sha256(&file.path)? != file.sha256 {
143	                return Err(GraphError::ArtifactBytesMismatch {
144	                    path: file.path.clone(),
145	                });
146	            }
147	        }
148	        Ok(())
149	    }
150	
151	    pub(super) fn mark_uploaded(&self, files: &[&BuiltFile]) {
152	        let mut uploaded = self.uploaded.lock().expect("uploaded list is never poisoned");
153	        uploaded.extend(files.iter().map(|file| file.filename.clone()));
154	    }
155	
156	    fn uploaded(&self) -> Vec<String> {
157	        self.uploaded.lock().expect("uploaded list is never poisoned").clone()
158	    }
159	}
160	
161	/// The sealed file set of every Python publish in `intent`, from the build output in `dir`.
162	pub(crate) fn seal_distributions(
163	    intent: &callisto_model::ReleaseIntentV1,
164	    dir: &Path,
165	) -> Result<Vec<callisto_model::DistributionSetV1>, GraphError> {
166	    let mut sets = Vec::new();
167	    for (package, rendered) in callisto_model::python_publishes(intent) {
168	        let version = intent
169	            .operations
170	            .iter()
171	            .map(|operation| operation.id())
172	            .find(|id| id.package == *package && id.version.render() == rendered)
173	            .map(|id| id.version.clone())
174	            .expect("a Python publish listed from the intent is in the intent");
175	        let files = inventory(dir, package.name(), &version)?
176	            .into_iter()
177	            .map(|file| {
178	                let byte_length = std::fs::metadata(&file.path).map_err(io_error)?.len();
179	                let digest = callisto_model::ArtifactDigest::parse(&file.sha256)
180	                    .expect("a SHA-256 hex digest is a canonical artifact digest");
181	                Ok(callisto_model::DistributionFileV1 {
182	                    filename: file.filename,
