197	/// How the index's files for a release differ from the files a build declared.
198	#[derive(Debug, Default, PartialEq, Eq)]
199	pub(super) struct Comparison<'a> {
200	    /// Declared files the index lacks.
201	    pub(super) missing: Vec<&'a str>,
202	    /// Declared files the index holds yanked.
203	    pub(super) yanked: Vec<&'a str>,
204	    /// Files whose index digest differs from the local file.
205	    pub(super) differing: Vec<&'a str>,
206	    /// Files the index holds for this release that no build declared.
207	    pub(super) extras: Vec<&'a str>,
208	}
209	
210	impl Comparison<'_> {
211	    /// Whether every declared file is on the index, with nothing to flag about it.
212	    pub(super) fn is_complete(&self) -> bool {
213	        self.missing.is_empty() && self.yanked.is_empty() && self.differing.is_empty()
214	    }
215	}
216	
217	/// Presence is by filename. A sealed set compares every digest; otherwise only files this run uploaded, as a
218	/// rebuild need not match an earlier attempt.
219	pub(super) fn compare<'a>(set: &'a BuiltSet, remote: &'a [PypiSimpleFile]) -> Comparison<'a> {
220	    let uploaded = set.uploaded();
221	    let mut comparison = Comparison::default();
222	    for file in &set.files {
223	        match remote.iter().find(|candidate| candidate.filename == file.filename) {
224	            None => comparison.missing.push(&file.filename),
225	            Some(held) if held.is_yanked() => comparison.yanked.push(&file.filename),
226	            Some(held) => {
227	                let unconfirmed = if set.sealed {
228	                    held.sha256() != Some(file.sha256.as_str())
229	                } else {
230	                    uploaded.contains(&file.filename) && held.sha256().is_some_and(|digest| digest != file.sha256)
231	                };
232	                if unconfirmed {
233	                    comparison.differing.push(&file.filename);
234	                }
235	            }
236	        }
237	    }
238	    comparison.extras = remote
239	        .iter()
240	        .map(|held| held.filename.as_str())
241	        .filter(|name| set.files.iter().all(|file| file.filename != *name))
242	        .collect();
243	    comparison
244	}
