46	    ) -> Result<super::ReleasePreflight, GraphError> {
47	        // An upload cannot be judged absent without the manifest that names
48	        // the exact bytes it would carry.
49	        request.artifacts.ok_or(GraphError::ReleasePreconditionUnmet {
50	            requirement: ReleasePreconditionRequirement::VerifiedArtifactManifest,
