60	    ) -> Result<ExactEvidence, GraphError> {
61	        let operation = artifact_operation(request)?;
62	        let artifacts = request.artifacts.ok_or(GraphError::ReleasePreconditionUnmet {
63	            requirement: ReleasePreconditionRequirement::VerifiedArtifactManifest,
64	        })?;
65	        let path = artifacts.path_for(&operation.slot)?;
66	        let repository = operation.slot.attestation_policy.repository.as_slug();
67	        confirmed_evidence(
68	            observe_until_visible(context.sleeper(), || {
69	                observed_draft_or_published_release(context, &operation.tag, operation.prerelease, &repository)
70	            })?,
71	            request.id,
72	            RemoteConflict::ForgeReleaseNotObservedAfterCreate,
73	        )?;
74	        let path_argument = path.to_string_lossy();
75	        let args = [
76	            "release",
77	            "upload",
78	            operation.tag.as_str(),
79	            path_argument.as_ref(),
80	            "--repo",
81	            repository.as_str(),
82	        ];
83	        let uploaded =
84	            context
85	                .runner()
86	                .run_with_timeout(programs::GH, &args, context.root(), timeouts::FORGE_ASSET_UPLOAD)?;
87	        if !uploaded.success() {
88	            return Err(GraphError::ReleaseCommand {
89	                program: programs::GH.to_owned(),
90	                args: args.iter().map(ToString::to_string).collect(),
91	                failure: CommandFailure::NonZeroExit {
92	                    exit_code: uploaded.exit_code,
93	                    stderr: uploaded.stderr,
94	                },
95	            });
96	        }
97	        confirmed_evidence(
98	            observe_until_visible(context.sleeper(), || {
99	                observe_artifact_upload(context, operation, Some(artifacts))
100	            })?,
