107	fn artifact_operation<'a>(request: &ProviderRequest<'a>) -> Result<&'a ArtifactUploadOperation, GraphError> {
108	    match request.operation {
109	        PreparedOperation::ArtifactUpload(operation) => Ok(operation),
110	        _ => Err(wrong_role(request.id, "artifact upload")),
111	    }
