113	
114	fn observe_artifact_upload(
115	    context: &ProviderContext<'_>,
116	    operation: &ArtifactUploadOperation,
117	    artifacts: Option<&super::VerifiedArtifactManifest<'_>>,
118	) -> Result<ProviderObservationV1, GraphError> {
119	    let Some(artifacts) = artifacts else {
120	        return Ok(ProviderObservationV1::Indeterminate {
121	            cause: ProviderIndeterminateCause::ArtifactManifestUnavailable,
122	        });
123	    };
124	    let entry = artifacts.entry_for(&operation.slot)?;
125	    let repository = operation.slot.attestation_policy.repository.as_slug();
126	    let release = match github_release_for_tag(
127	        context.root(),
128	        context.runner(),
129	        context.sleeper(),
130	        &repository,
131	        &operation.tag,
132	    )? {
133	        GitHubReleaseLookup::Absent => return Ok(ProviderObservationV1::Absent),
134	        GitHubReleaseLookup::Indeterminate { status } => {
135	            return Ok(ProviderObservationV1::Indeterminate {
136	                cause: ProviderIndeterminateCause::ProviderStatus { status },
137	            })
138	        }
139	        GitHubReleaseLookup::CommandFailed => {
140	            return Ok(ProviderObservationV1::Indeterminate {
141	                cause: ProviderIndeterminateCause::CommandFailed,
142	            })
143	        }
144	        GitHubReleaseLookup::Found(release) => release,
145	    };
146	    let assets = release
147	        .get("assets")
148	        .and_then(serde_json::Value::as_array)
149	        .ok_or_else(|| {
150	            malformed_github_response(
151	                &github_release_endpoint(
152	                    &repository,
153	                    release
154	                        .get("id")
155	                        .and_then(serde_json::Value::as_u64)
156	                        .unwrap_or_default(),
157	                ),
158	                "GitHub release response has no assets array",
159	            )
160	        })?;
161	    let matching: Vec<_> = assets
162	        .iter()
163	        .filter(|asset| {
164	            asset.get("name").and_then(serde_json::Value::as_str) == Some(operation.slot.asset_name.as_str())
165	        })
166	        .collect();
167	    match matching.as_slice() {
168	        [] => Ok(ProviderObservationV1::Absent),
169	        [asset] => {
170	            let digest = format!("sha256:{}", entry.digest.as_str());
171	            if asset.get("size").and_then(serde_json::Value::as_u64) == Some(entry.byte_length)
172	                && asset.get("digest").and_then(serde_json::Value::as_str) == Some(digest.as_str())
173	            {
174	                Ok(ProviderObservationV1::Exact {
175	                    evidence: ProviderEvidenceV1::ArtifactUpload {
176	                        byte_length: entry.byte_length,
177	                        sha256: entry.digest.clone(),
178	                    },
179	                })
180	            } else {
181	                Ok(ProviderObservationV1::Conflict {
182	                    reason: ProviderConflictReason::ArtifactAssetDiffers,
183	                })
184	            }
185	        }
186	        _ => Ok(ProviderObservationV1::Conflict {
187	            reason: ProviderConflictReason::DuplicateArtifactAsset,
188	        }),
189	    }
190	}
