12	/// that is there but cannot be read is an error, not a reason: the notes would silently differ from what was reviewed.
13	fn changelog_section(
14	    root: &Path,
15	    changelog: &Path,
16	    version: &Version,
17	) -> Result<Result<String, NotesFallback>, GraphError> {
18	    let path = root.join(changelog);
