44	impl ReleaseIntentV1 {
45	    /// Validates an already-parsed wire value into a well-formed intent.
46	    pub fn from_wire(wire: ReleaseIntentV1Wire) -> Result<Self, ReleaseIntentError> {
47	        if wire.schema_version != Self::SCHEMA_VERSION {
48	            return Err(ReleaseIntentError::UnsupportedSchemaVersion {
49	                type_name: "release intent",
50	                found: wire.schema_version,
51	                expected: Self::SCHEMA_VERSION,
52	            });
53	        }
54	        if !ReleaseDecisionV1::READABLE_SCHEMA_VERSIONS.contains(&wire.decision.schema_version) {
55	            return Err(ReleaseIntentError::UnsupportedSchemaVersion {
56	                type_name: "release intent decision",
57	                found: wire.decision.schema_version,
58	                expected: *ReleaseDecisionV1::READABLE_SCHEMA_VERSIONS.last().expect("nonempty"),
59	            });
60	        }
61	        if wire.snapshot.schema_version != ReleaseInputSnapshotV1::SCHEMA_VERSION {
62	            return Err(ReleaseIntentError::UnsupportedSchemaVersion {
63	                type_name: "release intent snapshot",
64	                found: wire.snapshot.schema_version,
65	                expected: ReleaseInputSnapshotV1::SCHEMA_VERSION,
66	            });
67	        }
68	        if wire.snapshot.packages.windows(2).any(|pair| pair[0] >= pair[1]) {
69	            return Err(ReleaseIntentError::PackagesNotCanonical);
70	        }
71	        let intent = Self::new(
72	            wire.decision,
73	            wire.snapshot,
74	            wire.trust_profile,
75	            wire.operations,
76	            wire.artifact_slots,
77	        )?;
78	        if intent.digest != wire.digest {
79	            return Err(ReleaseIntentError::DigestMismatch);
80	        }
81	        Ok(intent)
82	    }
83	}
