100	    pub fn new(
101	        decision: ReleaseDecisionV1,
102	        snapshot: ReleaseInputSnapshotV1,
103	        trust_profile: ExecutionTrustProfileV1,
104	        operations: Vec<ReleaseOperation>,
105	        mut artifact_slots: Vec<ArtifactSlotId>,
106	    ) -> Result<Self, ReleaseIntentError> {
107	        if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit)
108	            || !matches!(snapshot.source, SourceIdentity::GitCommit { .. })
109	        {
110	            return Err(ReleaseIntentError::UnsupportedTrustProfile);
111	        }
112	        validate_operations(&operations)?;
113	        validate_operation_roster(&decision, &operations)?;
114	        artifact_slots.sort();
115	        if artifact_slots.windows(2).any(|pair| pair[0] == pair[1]) {
116	            return Err(ReleaseIntentError::DuplicateArtifactSlot);
117	        }
118	        if let Some(slot) = artifact_slots.iter().find(|slot| {
119	            !decision
120	                .entries
121	                .iter()
122	                .any(|entry| entry.package == slot.package && entry.target_version == slot.version)
123	        }) {
124	            return Err(ReleaseIntentError::ArtifactSlotOutsideDecision {
125	                package: slot.package.to_string(),
126	                version: slot.version.to_string(),
127	                asset: slot.asset_name.clone(),
128	            });
129	        }
130	        validate_artifact_upload_roster(&operations, &artifact_slots)?;
131	        let digest = digest_intent(&decision, &snapshot, trust_profile, &operations, &artifact_slots);
132	        Ok(Self {
133	            schema_version: Self::SCHEMA_VERSION,
134	            decision,
135	            snapshot,
