148	fn digest_intent(
149	    decision: &ReleaseDecisionV1,
150	    snapshot: &ReleaseInputSnapshotV1,
151	    trust_profile: ExecutionTrustProfileV1,
152	    operations: &[ReleaseOperation],
153	    artifact_slots: &[ArtifactSlotId],
154	) -> IntentDigest {
155	    let mut transcript = CanonicalTranscript::intent_v1();
156	    transcript.push_bytes("schema", [ReleaseIntentV1::SCHEMA_VERSION]);
157	    transcript.push_str("decision", decision.digest.as_str());
158	    transcript.push_str("snapshot", snapshot.digest().as_str());
159	    transcript.push_str(
160	        "trust-profile",
161	        match trust_profile {
162	            ExecutionTrustProfileV1::GitCommit => "git-commit",
163	            ExecutionTrustProfileV1::HermeticContent => "hermetic-content",
164	        },
165	    );
166	    for operation in operations {
167	        transcript.push_str("operation", &operation_id_text(&operation.id));
168	        for prerequisite in &operation.prerequisites {
169	            transcript.push_str("prerequisite", &operation_id_text(prerequisite));
170	        }
171	    }
172	    for slot in artifact_slots {
173	        transcript.push_str("artifact-slot.package", &slot.package.to_string());
174	        transcript.push_str("artifact-slot.version", slot.version.render());
175	        transcript.push_str("artifact-slot.platform", &slot.platform);
176	        transcript.push_str("artifact-slot.asset", &slot.asset_name);
177	        transcript.push_str(
178	            "artifact-slot.repository",
179	            &slot.attestation_policy.repository.as_slug(),
180	        );
181	        transcript.push_str("artifact-slot.workflow-path", &slot.attestation_policy.workflow_path);
182	        transcript.push_str(
183	            "artifact-slot.workflow-commit",
184	            slot.attestation_policy.workflow_commit.as_str(),
185	        );
186	    }
187	    IntentDigest::from_transcript(&transcript)
188	}
