194	    let roster = &decision.entries;
195	    for operation in operations {
196	        if !roster
197	            .iter()
198	            .any(|entry| entry.package == operation.id.package && entry.target_version == operation.id.version)
199	        {
200	            return Err(ReleaseIntentError::OperationOutsideDecision {
