224	    let role = match &id.role {
225	        ReleaseOperationRole::RegistryPublish { registry } => format!(
226	            "publish:{}:{}",
227	            registry.registry_key().as_str(),
228	            registry.binding_digest().as_str()
229	        ),
230	        ReleaseOperationRole::Tag => "tag".to_string(),
231	        ReleaseOperationRole::ForgeRelease => "forge-release".to_string(),
232	        ReleaseOperationRole::ArtifactUpload { slot } => format!(
233	            "artifact-upload:{}:{}:{}:{}:{}:{}",
234	            slot.platform,
235	            slot.asset_name,
